update content_bodies set title = '小浜島の星の島 沖縄', description = '小浜島は沖縄本島から南に400kmの位置にあり、日本最大のサンゴ礁と有名な西表石垣国立公園に囲まれた理想的なリゾート地です。「HAIMURUBUSHI」という名のリゾートは、南十字星にちなんで名付けられ、八重山諸島の中で独自の体験を提供します。自然の美しさとリラクゼーションを求める旅行者にとって、完璧な目的地です。' where id = 'tEe-bpoL6-bNNwo4gRmPc';
update content_bodies set title = 'Star island Kohama Okinawa', description = 'Kohama Island, located 400 km south of Okinawa''s main island, is an ideal vacation resort surrounded by Japan''s largest coral reefs and the renowned Iriomote-Ishigaki National Park. The resort, named HAIMURUBUSHI after the Southern Cross, offers a unique experience in the Yaeyama Islands, making it a perfect destination for travelers seeking natural beauty and relaxation.' where id = 'qgj3qB3VUP0csCgq9nKQT';
update content_bodies set title = '動画で見る星空「星降る島 小浜島」', description = '沖縄本島から南へ400kmの場所に位置する小浜島のリゾート「はいむるぶし」では、日本のほとんどの地域で失われた本物の星空や天の川を見ることができます。目の前に降ってくる星々の光に囲まれる未知の体験を提供し、訪れる人々に特別なひとときをもたらします。' where id = '9mSirjdIjTkS5oe1h1X6k';
update content_bodies set title = 'Starry Sky in Video: Kohama Island', description = 'Located 400 km south of Okinawa''s main island, Kohama Island offers a unique resort experience at ''Haimurubushi,'' where visitors can witness the authentic starry sky and the Milky Way, which have been lost in most parts of Japan. This resort provides an extraordinary experience surrounded by the light of falling stars.' where id = 'NKnNAwwWNOb1lPIeEWKRw';
update content_bodies set title = 'はいむるぶしヨガ02【元気になれるヨガ】', description = '沖縄の離島に広がる癒しの風景を背景に、お部屋でヨガを楽しむことで心身を癒すことができます。このヨガセッションは、美しい景色の中でリフレッシュし、安らぎを見つける機会を提供します。#はいむるぶし #小浜島 #八重山諸島 #リゾート #旅行 #ホテル #風景' where id = 'Ym7twLhHoh5_S22zjdnF9';
update content_bodies set title = 'Haimurubushi Yoga 02: Yoga to Revitalize', description = 'Experience the healing landscapes of Okinawa''s remote islands while practicing yoga in your room. This session offers a chance to rejuvenate and find peace amidst the beautiful scenery. #Haimurubushi #Kohamajima #YaeyamaIslands #Resort #Travel #Hotel #Scenery' where id = 'kr6-HC-WF-bg1J2iZ_JKw';
