update content_bodies set title = 'はいむるぶし 西表島トレッキング・カヤック', description = '「はいむるぶし」は、八重山諸島の小浜島に位置するリゾートで、沖縄本島から南へ400kmの場所にあります。国内最大のサンゴ礁と西表石垣国立公園に囲まれたこのアイランドリゾートは、自然愛好者にとって理想的な休日を提供します。リゾート名は南十字星に由来し、星々と周囲の自然美とのつながりを象徴しています。訪れる人々は、トレッキングやカヤックを楽しみながら、素晴らしい風景と豊かな生物多様性に浸ることができます。' where id = 'TdXWw6aMLrWEFC0YC49Yi';
update content_bodies set title = 'Haimurubushi Iriomote Island Trekking and Kayaking', description = 'Haimurubushi is a unique resort located in the Yaeyama Islands, specifically on Kohama Island, 400 km south of Okinawa Main Island. Nestled within the largest coral reef in Japan and the Iriomote-Ishigaki National Park, it offers a perfect getaway for nature lovers. The resort is named after the Southern Cross, symbolizing its connection to the stars and the natural beauty surrounding it. Visitors can enjoy trekking and kayaking, immersing themselves in the stunning landscapes and rich biodiversity of the area.' where id = 'AQajeLfdPNge9KBajYefj';
