update content_bodies set title = 'Haimurubushi Prosperity Festival (Yaeyama Folk Song)', description = 'Experience the unique charm of Okinawa at Haimurubushi, a resort named after the Southern Cross. Located on Kohama Island, part of the Yaeyama Islands, it is situated 400 km south of Okinawa''s main island. The resort is surrounded by the largest coral reef in Japan and the Iriomote-Ishigaki National Park, offering a perfect getaway for nature lovers and travelers seeking relaxation in a beautiful island setting.' where id = 'oOosXALZbinmxK6MEByTK';
update content_bodies set title = '南十字星という名のリゾート”はいむるぶし”', description = '「はいむるぶし」は、八重山諸島の小浜島に位置するリゾートで、沖縄本島からさらに南へ400kmの場所にあります。国内最大のサンゴ礁と西表石垣国立公園に囲まれたこのアイランドリゾートは、特別な沖縄の休日を提供します。リラックスと冒険が融合した完璧なひとときを楽しむことができます。' where id = 'StHpPPclGh5TjOhpq5b9o';
