update content_bodies set title = 'Experience Haimurubushi to the Fullest!', description = 'Haimurubushi is a unique resort located in the Yaeyama Islands, specifically on Kohama Island, 400 km south of Okinawa Main Island. Nestled within the largest coral reef in Japan and the Iriomote-Ishigaki National Park, this island resort offers a perfect getaway. Visitors can enjoy the beauty of Okinawa, making it a special destination that showcases the region''s natural wonders.' where id = 'WreVrJF8WjtvElufVFRuR';
update content_bodies set title = 'はいむるぶし ２人の物語', description = '「はいむるぶし」は、八重山諸島の小浜島に位置するユニークなリゾートです。沖縄本島から南へ400kmの距離にあり、国内最大のサンゴ礁と西表石垣国立公園に囲まれています。このアイランドリゾートは、南十字星という名に由来し、地域の自然美とのつながりを強調しています。はいむるぶしは、リラクゼーションと冒険が融合した理想的な旅行先であり、沖縄の美しい風景と豊かな文化を体験したい旅行者に最適です。' where id = 'ZzAhphA295WQxEBeAdp-b';
update content_bodies set title = 'Haimurubushi: A Story of Two', description = 'Haimurubushi is a unique resort located in the Yaeyama Islands, specifically on Kohama Island, 400 km south of Okinawa''s main island. Nestled within the largest coral reef in Japan and the Iriomote-Ishigaki National Park, this island resort offers a tranquil getaway. The resort is named after the Southern Cross star, emphasizing its connection to the natural beauty of the region. Haimurubushi provides a perfect blend of relaxation and adventure, making it an ideal destination for travelers seeking to experience the stunning landscapes and rich culture of Okinawa.' where id = 'iRu3jKBf0q7NsiQtOO0on';
update content_bodies set title = 'はいむるぶしofficial movie', description = '「はいむるぶし」は、八重山諸島の小浜島に位置するリゾートで、沖縄本島からさらに南へ400kmの場所にあります。国内最大のサンゴ礁と西表石垣国立公園に囲まれたこのアイランドリゾートは、特別な休日を提供します。映画では、沖縄の美しさが紹介されており、旅行者にこの静かな目的地を探求することを促しています。' where id = 'jA7ByiG95VJ6vK0BzzTdw';
update content_bodies set title = 'Haimurubushi Official Movie', description = 'Haimurubushi is a resort located on Kohama Island in the Yaeyama Islands, 400 km south of Okinawa''s main island. Nestled within the largest coral reef in Japan and the Iriomote-Ishigaki National Park, it offers a unique island resort experience. The movie showcases the beauty of Okinawa, inviting travelers to explore this serene destination.' where id = '5bhimsxb_e_5FM-4zmse2';
