update content_bodies set title = 'Haimurubushi Sailing', description = 'Haimurubushi is a unique resort located in the Yaeyama Islands, specifically on Kohama Island, 400 km south of Okinawa''s main island. Nestled within the Iriomote-Ishigaki National Park, it offers a holiday experience surrounded by Japan''s largest coral reef, the Ishigaki Coral Lagoon. Guests can enjoy elegant cruising on a catamaran yacht, taking in the stunning Yaeyama Blue and the islands of Yaeyama from the sea.' where id = 'Ve6gp9kIwvEixp0ds8uMK';
