update content_bodies set title = 'Haimurubushi Snorkeling', description = 'Haimurubushi is a resort located on Kohama Island, part of the Yaeyama Islands, 400 km south of Okinawa Main Island. Nestled within the largest coral reef in Japan and the Iriomote-Ishigaki National Park, it offers a unique island resort experience. The area around Kohama Island features a variety of snorkeling points, and Haimurubushi provides guidance to the best spots based on weather and sea conditions.' where id = '1iQyCrae_DG8A9I5j11vZ';
