update content_bodies set title = 'Haimurubushi Stand Up Paddle Surfing', description = 'Experience the unique beauty of Okinawa at Haimurubushi, a resort named after the Southern Cross. Located on Kohama Island in the Yaeyama Islands, it is situated 400 km south of Okinawa Main Island, surrounded by the largest coral reef in Japan and the Iriomote-Ishigaki National Park. Enjoy a holiday at this island resort, where you can fully enjoy stand-up paddleboarding (SUP) in the stunning blue waters of the largest coral reef in the country. The breathtaking views from the water will leave you in awe.' where id = '4-ZLUskfNjpF1rmU9VU3U';
