update content_bodies set title = '【私のイチ推し鹿児島コンテスト 優秀賞】 ホノホシ海岸', description = 'この動画では、私のイチ推し鹿児島コンテストで優秀賞に選ばれたホノホシ海岸について紹介しています。ホノホシ海岸はその美しい景観や独特の魅力で知られており、訪れる人々に感動を与えています。' where id = 'GJpm2oXRlCvhg3XswFk7q';
update content_bodies set title = 'Honohoshi Coast - Awarded in My Favorite Kagoshima Contest', description = 'This video introduces Honohoshi Coast, which was selected as an excellent award in the ''My Favorite Kagoshima Contest.''' where id = 'TCbB10KbCZlWTLe-XyXBc';
update content_bodies set title = '私のイチ推し鹿児島コンテスト 最優秀賞: 水の島　屋久島', description = 'この動画では「私のイチ推し鹿児島コンテスト」の最優秀賞を受賞した屋久島について紹介しています。屋久島はその美しい自然と豊かな水資源で知られ、訪れる人々に感動を与えています。' where id = 'uKVWRYmCZ2a0z6bvaVtHE';
update content_bodies set title = 'My Favorite Kagoshima Contest Grand Prize: Yakushima, the Island of Water', description = 'This video introduces the Grand Prize winner of the ''My Favorite Kagoshima Contest''.' where id = 'oTzXIZMLPCudbE4vDbCj5';
update content_bodies set title = '私のイチ推し鹿児島コンテスト 優秀賞', description = 'この動画では「私のイチ推し鹿児島コンテスト 優秀賞」について紹介しています。鹿児島の魅力や特産品、文化などが詰まったコンテストで、優秀賞を受賞した作品を通じて、視聴者にその素晴らしさを伝えています。鹿児島の本物の魅力を感じることができる内容となっており、地域の特性や人々の情熱が表現されています。' where id = 'AyKbbP3U4ZM5fqy4UDsDM';
update content_bodies set title = 'My Favorite Kagoshima Contest - Excellence Award', description = 'This video introduces the ''My Favorite Kagoshima Contest - Excellence Award''.' where id = 'SSKEgNs5iHDewqFm7syFJ';
update content_bodies set title = '私のイチ推し鹿児島コンテスト 優秀賞', description = 'この動画では「私のイチ推し鹿児島コンテスト 優秀賞」について紹介しています。鹿児島の魅力や特産品、文化などが評価されるこのコンテストは、地域の活性化を目的としており、多くの参加者が自分の推しをアピールしています。優秀賞を受賞した作品は特に注目され、鹿児島の素晴らしさを広める役割を果たしています。' where id = 'OQaUthVxHwg1cH97tL5Fg';
update content_bodies set title = 'My Favorite Kagoshima Contest Excellence Award', description = 'This video introduces the ''My Favorite Kagoshima Contest Excellence Award''.' where id = 'coPjZ7jQQWZwhKXDRfJKt';
update content_bodies set title = '【私のイチ推し鹿児島コンテスト 優秀賞】', description = 'この動画では「私のイチ推し鹿児島コンテスト 優秀賞」について詳しく紹介しています。鹿児島の魅力や素晴らしい人々を伝える内容となっており、視聴者にとって興味深い情報が盛り込まれています。' where id = 'k7cvzoCo4GozHwvBBjiu6';
update content_bodies set title = 'My Favorite Kagoshima Contest Excellence Award', description = 'This video introduces the ''My Favorite Kagoshima Contest Excellence Award''.' where id = 'y1wCifRlfBwYTkPjP9P0C';
update content_bodies set title = '【かごしまサイクルツーリズム】薩摩藩が誇る武家の歴史と絢爛な文化が薫る街並みを走る！南薩ルートver2', description = '「サイクリングターミナルりんりん」を起点とするこのルートでは、南さつま市、日置市、鹿児島市、指宿市、南九州市、枕崎市の各地域の特徴的な風景を楽しむことができます。リアス式海岸線を背景にした東シナ海の美しい夕日や、桜島、開聞岳がそびえる錦江湾の景色は格別です。また、武家屋敷群や薩摩焼の窯元、焼酎の酒蔵、鰹本枯れ節の工場など、魅力的なスポットが点在しています。' where id = 'tRe_6pCa_TfMEUHEZ6fwE';
update content_bodies set title = 'Kagoshima Cycle Tourism: Ride Through the Historic Streets of the Satsuma Domain', description = 'This cycling route starts and ends at the ''Cycling Terminal Rinrin'' and takes you through the scenic areas of Minamisatsuma City, Hioki City, Kagoshima City, Ibusuki City, Minamikyushu City, and Makurazaki City. Cyclists can enjoy the beautiful sunset over the East China Sea, framed by the ria coastline, as well as the stunning views of Sakurajima and Kaimondake rising over Kinko Bay. The area is rich in attractions, including samurai residences, Satsuma pottery kilns, shochu distilleries, and katsuobushi (dried bonito) factories.' where id = 'veI0PzlLH5p7Aai_p5lFK';
update content_bodies set title = '【かごしまサイクルツーリズム】美しい名峰と癒やしの温泉で身も心もあたたまる！霧島・姶良ルートver2', description = '鹿児島空港を拠点にした8の字のサイクリングルートです。神話や伝説に彩られた霧島連山の名峰を間近に感じられ、火山の息吹を体感できます。清流は四季折々に神秘的な表情を見せ、その自然美は感動的です。また、鹿児島の中心に位置する姶良では、文化史跡が溶け込む街並みや、緑豊かな山々、輝く錦江湾、温泉を楽しむことができます。' where id = '4RmXHHd2cl2Ovczkk2AXM';
update content_bodies set title = 'Kagoshima Cycle Tourism: Warm Your Body and Soul with Beautiful Peaks and Healing Hot Springs! Kirishima-Aira Route ver2', description = 'This cycling route, centered around Kagoshima Airport, forms a figure-eight loop. It is adorned with myths and legends, allowing riders to feel the breath of the volcanic Kirishima mountain range. The clear streams exhibit a mystical beauty that changes with the seasons, providing an emotional experience. The route also includes Aira, located in the heart of Kagoshima, where cultural historical sites blend with the vibrant cityscape, as well as lush green mountains, the sparkling Kinko Bay, and relaxing hot springs.' where id = 'wVhat-JYjWwLx8LkI7zz3';
update content_bodies set title = '【かごしまサイクルツーリズム】霧島連山を背景に豊かに流れ出す川沿いの風景を楽しむ！川内川（せんだいがわ）流域ルートver2', description = '吉松駅を出発し、川内川沿いに高速船ターミナル（川内港）へ向かうサイクリングルートです。途中には湧水池や、東洋のナイアガラと称される迫力ある曽木の滝、夏の風物詩であるほたるなど、見どころが満載です。霧島山系の豊かな水に支えられた稲穂の田園や、銘茶を生産する茶畑の美しい風景が広がり、川沿いの旅を楽しむことができます。' where id = 'ziMt0J2H2RdCzKlt53wer';
update content_bodies set title = 'Kagoshima Cycle Tourism: Enjoying the Scenic Views Along the Sendai River with the Kirishima Mountain Range in the Background!', description = 'Starting from Yoshimatsu Station, this cycling route leads along the Sendai River to the high-speed boat terminal at Sendai Port. Along the way, cyclists can enjoy various attractions, including bubbling spring water pools, the dynamic Sogi Falls, known as the ''Niagara of the East,'' and the summer spectacle of fireflies. The route continues along the river to the estuary that connects to the East China Sea, showcasing the lush rice fields supported by the abundant waters of the Kirishima mountain range and the picturesque tea plantations.' where id = 'DIW9WTZcAM2zrYbd7F3SC';
update content_bodies set title = '世界自然遺産　奄美大島', description = '奄美大島は2021年7月に世界自然遺産に登録されました。鹿児島県は「屋久島」と合わせて、2つの世界自然遺産を有する唯一の都道府県となりました。奄美大島は、手つかずの自然風景が連続しており、訪れる人々に癒しを提供します。また、奄美を舞台としたアドベンチャーツアーも造成されており、観光客に新たな体験を提供しています。' where id = 'KR2SR8NA8DVlda5WMVESt';
update content_bodies set title = 'Amami Oshima: A World Natural Heritage Site', description = 'Amami Oshima was registered as a World Natural Heritage site in July 2021. Kagoshima Prefecture is the only prefecture in Japan to have two World Natural Heritage sites, including Yakushima. The island features pristine natural landscapes that provide healing experiences for visitors.' where id = 'kRjrv1AhFSZxOsY_Qiriu';
update content_bodies set title = '岡山｜日本 - 美咲町と津山城！', description = 'このルートでは、美咲町の美しい棚田、映画のロケ地となったフォトジェニックな公園、そして津山市の歴史的な町並みを紹介します。朝食には美咲の卵かけご飯、昼食には津山ホルモンうどんなど、地元の独特な料理を楽しむことができます。主な観光スポットには、日本の棚田百選に選ばれた大ヶ西の棚田、やなはら鉱山公園、重要伝統的建造物群保存地区の城東町並みがあります。さらに、PORT ART & DESIGN TSUYAMAや旧梶村家住宅などの見どころもあり、神楽饅頭などの土産物も手に入ります。写真撮影やグルメを楽しむには最適な旅です。' where id = 'EQtywLs-FuYNa2thcG--v';
update content_bodies set title = 'Okayama, Japan - Misaki Town and Tsuyama City!', description = 'This route showcases the stunning rice field terraces of Misaki-cho, a picturesque park that has been featured in films, and the historic townscape of Tsuyama City. Visitors can enjoy unique local cuisine, including Misaki Tamago Kake Gohan for breakfast and Tsuyama Horumon Udon for lunch. Key attractions include the top-rated rice field terrace of Ohaganishi, Yanahara Mine Park, and the Important Preservation District for Groups of Traditional Buildings in Joto. Additional highlights are the PORT ART & DESIGN TSUYAMA and the traditional townhouse of former Kajimura residents. Souvenirs like Godai Hokuten Manju are also available, making this trip a delightful experience for both photography and culinary enthusiasts.' where id = 'OZOMEFHrAGmY26upFCbBz';
update content_bodies set title = '【かごしまサイクルツーリズム】歴史ロマンあふれる！甑島ルートをサイクリング！', description = '上甑島・中甑島・下甑島といちき串木野市を周遊するサイクリングルートです。サイクリングの醍醐味である橋を渡る爽快感を存分に味わえます。甑島の断崖には8000万年前の地層が残り、歴史的な名所として日本遺産に認定された武士の町「麓」や、薩摩藩英国留学生記念館など、歴史ロマンあふれるスポットが点在しています。ぜひこの旅を楽しんでください。' where id = 'e8jUC2FEMLvcrJ9uLWNAs';
update content_bodies set title = 'Kagoshima Cycle Tourism: Cycling the Romantic Historical Koshikijima Route!', description = 'This cycling route takes you around Upper, Middle, and Lower Koshikijima Islands and Ichiki-Kushikino City. Experience the exhilarating feeling of crossing bridges, a highlight of cycling. The route features stunning cliffs with geological formations dating back 80 million years, and includes historical sites such as the samurai town recognized as a Japanese Heritage site, the ''Fumoto'' samurai residences, and the ''Satsuma Student Memorial Museum'' that commemorates the Satsuma students who contributed to Japan''s modernization. Enjoy a journey filled with historical romance.' where id = 'yQg3UiBSVBqbQS68MN0jY';
update content_bodies set title = '宇宙を身近に感じる！種子島ルートをサイクリング！', description = '種子島ルートでは、宇宙を身近に感じられるエリアがあり、南の島らしいサトウキビ畑が両側に広がる風景を楽しみながらサイクリングできます。美しい海を臨むアイランドロードを存分に楽しむことができ、さらにサーフィンやヨガなどのアクティビティも体験できるため、種子島の豊かな自然を満喫することができます。' where id = 'EFz6yLX5j47LeYmegnMk3';
update content_bodies set title = 'Cycling the Tanegashima Route: Experience Space Up Close!', description = 'The Tanegashima Route offers a unique opportunity to feel closer to space, with areas that highlight the connection to the cosmos. Cyclists can enjoy beautiful island roads lined with sugarcane fields typical of southern islands, all while taking in stunning ocean views. In addition to cycling, visitors can also experience various activities such as surfing and yoga, allowing them to fully appreciate the rich natural beauty of Tanegashima.' where id = 'iyKSvcZxx0Yt_U6PHCFee';
update content_bodies set title = '【かごしまサイクルツーリズム】美しい名峰と癒やしの温泉で身も心もあたたまる！霧島・姶良ルート', description = '鹿児島空港を拠点にした8の字の周遊ルートです。神話や伝説に彩られた霧島連山の名峰では、火山の息吹を感じることができます。清流は四季折々に神秘的な表情を見せ、その自然美は感動的です。また、鹿児島の中央に位置する姶良では、文化史跡が溶け込む街並みを楽しむことができ、緑豊かな山々や輝く錦江湾、温泉も堪能できる魅力的なルートです。' where id = 'LL7QtlJRSCiBits18SffR';
update content_bodies set title = 'Kagoshima Cycle Tourism: Warm Your Body and Soul with Beautiful Peaks and Soothing Hot Springs! Kirishima and Aira Route', description = 'This route, centered around Kagoshima Airport, forms a figure-eight loop. It is adorned with myths and legends, allowing you to feel the breath of the volcanoes in the majestic Kirishima mountain range. The clear streams display a mystical beauty throughout the seasons, evoking deep emotions. Additionally, the route includes Aira, located in the heart of Kagoshima, where cultural historical sites blend with the vibrant cityscape. Enjoy the lush green mountains, the sparkling Kinko Bay, and the relaxing hot springs along the way.' where id = '7vzUxMnadj4Bl_ZHQvn42';
update content_bodies set title = 'スリル満点！御座白浜でトーイングチューブ【伊勢志摩グランピング】LUXUNA伊勢志摩　マリンアクティビティ', description = 'トーイングチューブは、ジェットスキーに引っ張られ、時速25kmから70kmで海上を疾走するスリリングなアクティビティです。刺激を求める方にぴったりで、スピードの調整は手の合図で行えます。70kmでの体験は非常に迫力があり、振り落とされないように必死で叫ぶことも難しいです。天候や波の状況によってスピードは変わりますが、運転手が工夫して楽しませてくれます。バナナボートよりもひっくり返りにくいため、女性や子供でも楽しみやすいですが、しっかり濡れるので、アクティビティ後の着替えとシャワーは必須です。この体験は、2021年7月にオープンした「ラグナ伊勢志摩」で提供されており、贅沢と自然を融合させた快適なグランピング施設です。料金は1名につき15分5,000円（税込）です。' where id = '50ecKNp9xuVQb1GvNuw5t';
update content_bodies set title = 'Thrilling Towable Tubing at Goza Shirahama | Ise-Shima Glamping LUXUNA Ise-Shima Marine Activities', description = 'Towable tubing is an exhilarating activity where participants are pulled by a jet ski at speeds ranging from 25 km/h to 70 km/h across the sea. It''s perfect for those seeking thrills! You can signal the jet ski driver to adjust the speed. At 70 km/h, the experience is intense, making it hard to scream as you try to hold on. The speed may vary depending on weather and wave conditions, but the jet ski driver will ensure you have a great time. This activity is less likely to flip than a banana boat, making it suitable for women and children. However, be prepared to get soaked, so a change of clothes and a shower afterward are essential! The experience is offered at ''Laguna Ise-Shima,'' a glamping facility that opened in July 2021, combining luxury and nature. The cost is 5,000 yen per person for a 15-minute session.' where id = 'x73wsXNObkk0UJUJrorKd';
update content_bodies set title = '丸山千枚田と熊野の秘湯めぐり', description = 'この動画では、三重県熊野市にある丸山千枚田と熊野の秘湯について紹介しています。美しい風景と温泉の魅力を楽しむことができる内容です。' where id = 'AR2ZDO61C66Oxf6CxPXBU';
update content_bodies set title = 'Exploring Maruyama Senmaida and Hidden Hot Springs in Kumano City, Mie Prefecture', description = 'This video introduces Maruyama Senmaida and the hidden hot springs in Kumano.' where id = 'pI8xMEGnaEyxRIV_OnO9K';
update content_bodies set title = '観光三重2017 101号　冬のオススメ観光20セレクション', description = 'この文章では、三重県の冬におすすめの観光スポットを紹介しています。伊勢神宮の内宮や外宮、おかげ横丁など、伊勢・鳥羽・志摩地域の観光情報が含まれています。また、宿泊施設やモデルコースのリンクも提供されています。三重県の観光、旅行、イベント、宿泊予約に関する詳細は、三重県観光連盟の公式サイトを訪れることで確認できます。' where id = 'UfC4F41k9qnp8MMuJ4ihv';
update content_bodies set title = 'Mie Tourism 2017 Issue 101: 20 Recommended Winter Attractions', description = 'This article introduces recommended winter spots in Mie Prefecture. It highlights attractions such as Ise Jingu Shrine, both the Inner and Outer Shrines, and Okage Yokocho, along with travel information for the Ise, Toba, and Shima areas. Additionally, it provides links to hotel accommodations and model courses for visitors. For more details on tourism, events, and lodging reservations in Mie Prefecture, visit the official Mie Prefecture Tourism Federation website.' where id = 'zVg7fQk5_aFIZ_jcgbD1e';
update content_bodies set title = '透明度抜群！御座白浜海水浴場でシーカヤック【伊勢志摩グランピング】LUXUNA伊勢志摩　マリンアクティビティ', description = '「クリアカヤック」をご存知でしょうか？透明なボディーとオールを持つカヤックで、三重県No.1の透明度を誇る御座白浜海水浴場の美しい海と相性抜群です。透き通ったカヤック越しに水中の様子を楽しむことができ、魚が真下を泳ぐ様子も観察できます。この体験は、2021年7月にオープンした「ラグナ伊勢志摩LUXUNA」で提供されており、贅沢と自然を融合させたグランピング施設です。快適な宿泊施設や豪華な食事、自然を楽しむアクティビティが揃っています。クリアカヤックはガイド付きプランで90分7,500円、通常のカラーカヤックは3,300円、ガイド付きプランは5,500円です。' where id = 'am3XiTMWD0Ip6iNKLwXJM';
update content_bodies set title = 'Crystal Clear! Sea Kayaking at Goza Shirahama Beach | Ise-Shima Glamping LUXUNA Marine Activities', description = 'Have you heard of ''clear kayaks''? These kayaks, made entirely of transparent material, are perfect for enjoying the stunningly clear waters of Goza Shirahama Beach, known for its top-notch transparency in Mie Prefecture. You can observe underwater life, including fish swimming right beneath you, through the clear kayak. The experience is offered at ''LUXUNA Ise-Shima'', a glamping facility that opened in July 2021, combining luxury and nature. LUXUNA provides comfortable accommodations, gourmet meals, and a variety of activities to enjoy the natural surroundings. The clear kayak experience is available only with a guided plan for 90 minutes at a price of 7,500 yen per person, while regular colored kayaks are available for 3,300 yen per person, or 5,500 yen with a guide.' where id = 'ETStsp5yxqEOseFreJqZu';
update content_bodies set title = '岡山｜日本 - 新しい岡山城！', description = '岡山城は令和時代に大規模な改修を行い、今年の11月3日に再オープンしました。特徴的な黒い外壁が再塗装され、岡山の歴史を映像や体験プログラムを通じて紹介する興味深い展示が行われています。城の塔のB1から6階までのフロアは、重要文化財が展示されている2階を除いて、夜間にパーティーやその他の活動のために貸し出すことができます。この動画では、岡山城の魅力と岡山城備前焼陶芸スタジオでの備前焼作りの体験を紹介しています。' where id = 'uO8JZ_6gIHk3FDAFprsvZ';
update content_bodies set title = 'Okayama, Japan - New Okayama Castle!', description = 'Okayama Castle has undergone major renovations during the Reiwa era, reopening on November 3rd. The castle features a striking black exterior, which has been repainted, and offers engaging exhibitions that showcase Okayama''s history through videos and interactive programs. Visitors can rent the castle tower''s floors from B1 to the 6th floor for evening events, except for the 2nd floor, which displays important cultural properties. The video highlights the charm of Okayama Castle and includes an experience of making Bizen-yaki pottery at the Okayama Castle Bizen-yaki Pottery Studio.' where id = '-iU75QDErj5QNvX5Ym6gW';
update content_bodies set title = 'シンデレラのフェアリーテイルホール完全ツアー | 東京ディズニーランド 2022', description = 'この動画は、2022年7月に訪れた東京ディズニーランドのシンデレラのフェアリーテイルホールの完全ツアーを提供します。視聴者は、公式の東京ディズニーリゾートのウェブサイトを通じて入場券を予約することが奨励されており、現在いくつかのチケットタイプが販売中です。動画には音楽が含まれており、すべてのコンテンツはそれぞれの所有者に帰属し、エンターテインメント目的でのみ使用されることが明記されています。紹介されている製品にはスポンサーシップはありません。' where id = 'mbWzmjNFYG6JCxaQ0zBF6';
update content_bodies set title = 'Cinderella’s Fairy Tale Hall Full Tour | Disneyland 2022 | Tokyo Disneyland', description = 'This video provides a complete tour of Cinderella''s Fairy Tale Hall at Tokyo Disneyland, filmed during a visit in July 2022. Viewers are encouraged to book their admission tickets through the official Tokyo Disney Resort website, where some ticket types are currently on sale. The video features music and includes a disclaimer stating that all content belongs to its respective owners and is intended for entertainment purposes only. No sponsorship is involved in the products shown.' where id = 'rqU_YJQW8irxb5pQsjSQJ';
update content_bodies set title = '東京ディズニーランドのトゥーンタウンにあるドナルドのボート | ミス・デイジー', description = '東京ディズニーランドのトゥーンタウンにあるドナルドのボート、ミス・デイジーを紹介します。このアトラクションでは、ボートのキャプテンになったり、大きなスライドで遊んだりすることができます。2022年7月のディズニーランド旅行からのフルツアーを収めた動画です。入場券は公式ウェブサイトから購入可能で、現在いくつかのチケットタイプが販売中です。動画には音楽が含まれており、すべてのコンテンツはそれぞれの所有者に帰属し、エンターテインメント目的であることを示す免責事項があります。' where id = 'hSYixQYlBuPOGVQcvyzBn';
update content_bodies set title = 'Donald’s Boat in Toontown Tokyo Disneyland | Miss Daisy', description = 'Explore Donald''s Boat, known as Miss Daisy, located in Toontown at Tokyo Disneyland. Visitors can experience being a boat captain inside the attraction and enjoy a large slide for play. This video showcases a full tour from a trip to Disneyland in July 2022. Admission tickets can be purchased through the official Tokyo Disneyland website, where some ticket types are currently on sale. The video features music and includes a disclaimer stating that all content belongs to their respective owners and is for entertainment purposes only.' where id = '9kHH_OWC3fNWCVJQpBdTt';
update content_bodies set title = 'グーフィーのペイント&プレイハウス 東京ディズニーリゾート', description = '東京ディズニーランドのグーフィーのペイント&プレイハウスでは、訪れる人々に楽しくインタラクティブな体験を提供しています。この動画は、2022年7月のディズニーランド旅行からのフルツアーを紹介しており、会場で楽しめるアクティビティを強調しています。入場券は公式の東京ディズニーランドウェブサイトを通じて購入でき、現在いくつかのチケットタイプが販売中です。また、動画には音楽が含まれており、すべてのコンテンツはそれぞれの所有者に帰属し、エンターテインメント目的でのみ使用されることが明記されています。' where id = '7wwMTm3PloXEFpjTMAzNN';
update content_bodies set title = 'Goofy''s Paint ''n'' Play House | Tokyo Disneyland Resort', description = 'Goofy''s Paint ''n'' Play House in Tokyo Disneyland offers a fun and interactive experience for visitors. This video showcases a full tour from a July 2022 trip to Disneyland, highlighting the enjoyable activities available at the venue. Admission tickets can be purchased through the official Tokyo Disneyland website, where some ticket types are currently on sale. The video also features music, with a disclaimer stating that all content belongs to their respective owners and is intended for entertainment purposes only.' where id = 'myZJ7whTREpFDWax9M__f';
update content_bodies set title = '鹿児島３つの世界遺産', description = '2021年7月に「奄美大島，徳之島，沖縄島北部及び西表島」が世界自然遺産に登録されたことで、鹿児島県は「屋久島」と合わせて2つの世界自然遺産を有する唯一の都道府県となりました。また、世界文化遺産「明治日本の産業革命遺産」を加えると、鹿児島県には3つの世界遺産があります。それぞれの世界遺産は、鹿児島県の歴史や文化、大自然の異なる魅力を楽しむことができます。' where id = 'sHQzCzh9WePl1gHtDPtgs';
update content_bodies set title = 'Three World Heritage Sites in Kagoshima', description = 'In July 2021, the registration of ''Amami Oshima, Tokunoshima, Northern Okinawa Island, and Iriomote Island'' as a World Natural Heritage site made Kagoshima Prefecture the only prefecture in Japan to have two World Natural Heritage sites, alongside Yakushima. When combined with the World Cultural Heritage site ''Sites of Japan''s Meiji Industrial Revolution,'' Kagoshima boasts three World Heritage sites. Visitors can enjoy the unique history, culture, and natural beauty that each of these heritage sites offers.' where id = 'Ua1Y7cimwGXMG8HaM5iRc';
update content_bodies set title = '東京デイズニーランド | ミニーマウスとのミート＆グリート', description = '東京デイズニーランドのミニーマウスの可愛らしいスタイルスタジオでのミート＆グリートを体験しましょう。この動画では、2022年7月の訪問時に撮影された新しく改装されたミニーマウスの家のフルツアーが紹介されています。入場券は公式の東京ディズニーリゾートのウェブサイトから購入可能で、現在いくつかのチケットタイプが販売中です。また、動画には音楽が含まれており、すべてのコンテンツはそれぞれの所有者に帰属し、エンターテインメント目的でのみ使用されることが明記されています。' where id = '3yEgb0CVEeytOR8CRizk-';
update content_bodies set title = 'Tokyo Disneyland | Meet and Greet with Minnie Mouse at Minnie’s Style Studio', description = 'Experience a delightful meet and greet with Minnie Mouse at her charming Style Studio in Tokyo Disneyland. The video showcases a full tour of the newly renovated Minnie Mouse House, captured during a visit in July 2022. Visitors can purchase admission tickets through the official Tokyo Disney Resort website, where some ticket types are currently on sale. The video also features music, with a disclaimer stating that all content belongs to their respective owners and is intended for entertainment purposes only.' where id = 'E8ZqLknc492vIIsg9OezL';
update content_bodies set title = '【かごしまサイクルツーリズム】日本の原風景を走る！北薩ルート', description = '熊本県との県境に位置する北薩は、懐かしい里山の風景や風光明媚な温泉が楽しめる場所です。白い砂浜が続く美しい海岸線では、東シナ海に沈むオレンジ色の夕日に癒されます。また、海の幸や山の幸が豊かな北薩地域のご当地グルメも楽しみの一つです。さらに、歴史ロマンあふれる甑島ルートや、宇宙を身近に感じる種子島ルート、癒やしの自然で深呼吸できる屋久島ルートなど、他の動画もぜひご覧ください。' where id = 'B6EXiE4NLVZR5CrfrcyH1';
update content_bodies set title = 'Kagoshima Cycle Tourism: Ride Through Japan''s Scenic Landscapes! North Satsuma Route', description = 'Located at the border with Kumamoto Prefecture, North Satsuma offers nostalgic rural landscapes and beautiful hot springs. The stunning coastline features white sandy beaches, where visitors can enjoy the soothing sight of orange sunsets over the East China Sea. Additionally, the region is known for its rich local cuisine, showcasing the abundance of seafood and mountain delicacies. Explore more routes through the provided video links, including the historical Koshikijima Route, the space-themed Tanegashima Route, and the nature-filled Yakushima Route.' where id = 'Wlt9NneCpqUhciqBSCrp5';
update content_bodies set title = '【かごしまサイクルツーリズム】宇宙を身近に感じる！種子島ルート', description = '種子島ルートでは、宇宙を身近に感じられるエリアや、南の島らしいサトウキビ畑が広がる風景を楽しみながらサイクリングができます。美しい海を臨むアイランドロードを走ることができ、種子島の豊かな自然を満喫することができます。また、サーフィンやヨガなどのアクティビティも体験できるため、自然を楽しむ良い機会となるでしょう。' where id = 'FxTH6eAIU_8v6tH7fc8nn';
update content_bodies set title = 'Tanegashima Route: Experience Space Up Close!', description = 'The Tanegashima Route offers a unique opportunity to feel closer to space, surrounded by beautiful landscapes featuring sugarcane fields typical of southern islands. Cyclists can enjoy the scenic island road overlooking the ocean. In addition to cycling, visitors can also experience various activities such as surfing and yoga, allowing them to fully appreciate the rich natural environment of Tanegashima.' where id = '9oFHRG06NyH2zOe3lcFCH';
update content_bodies set title = 'なばなの里イルミネーション（三重県桑名市）', description = '三重県桑名市に位置する「なばなの里」のイルミネーションは、世界的に有名で多くの人々に愛されています。このイベントでは、毎年美しい光の演出が行われ、多くの観光客を惹きつけています。2018-2019年のイルミネーションに関する詳細な情報（期間、料金、アクセスなど）は、提供されたリンクから確認できます。また、桑名市や周辺の町を含む北勢エリアのおすすめ観光スポットについての情報もあります。三重県の観光、イベント、宿泊予約に関しては、三重県観光連盟の公式サイトが役立つ情報源です。' where id = 'Y0_tMV2fIBNckLQ51FLU9';
update content_bodies set title = 'Nabana no Sato Illumination (Kuwana City, Mie Prefecture)', description = 'The illumination at Nabana no Sato in Kuwana City, Mie Prefecture, is world-renowned and highly popular. The event features stunning light displays that attract many visitors each year. For detailed information about the 2018-2019 illumination event, including dates, prices, and access, you can visit the provided links. Additionally, there are resources available for exploring recommended tourist spots in the northern Ise area, including Kuwana City and surrounding towns. For more information on tourism, events, and accommodations in Mie Prefecture, the official Mie Prefecture Tourism Federation website is a valuable resource.' where id = 'Bp5K7XnkFLZLZiCIQgsQz';
update content_bodies set title = 'チューリップガーデン公開イベント | オランダ王国大使館', description = 'オランダ王国大使館は、2022年4月8日と10日にチューリップガーデンの公開イベントを開催しました。これは、オランダの春を祝うもので、70種類のチューリップが展示され、過去最大の規模となりました。チューリップはオランダの国花であり、重要な輸出品で、世界の約80%のチューリップ畑がオランダにあります。今年は大使公邸に約13,000本のチューリップが飾られ、オランダからの最大の輸入量を記録しました。参加者は美しい花々を楽しみ、思い出に残る写真や動画を撮影しました。この貴重な機会を提供してくださった大使に特別な感謝が述べられました。' where id = 'DiVmyVmsvRhlzQ0i9zFzj';
update content_bodies set title = 'Residence and Tulip Garden Public Viewing | Embassy of the Netherlands in Japan', description = 'The Embassy of the Kingdom of the Netherlands in Japan held a Residence and Tulip Garden Public Viewing on April 8 and 10, 2022, to celebrate Dutch Spring. This year featured an impressive display of 70 varieties of tulips, the largest number ever showcased. Tulips, the national flower of the Netherlands, are a significant export, with around 80% of the world''s tulip fields located in the country. The Ambassador''s residence was adorned with approximately 13,000 tulips, marking a record import from the Netherlands. Attendees enjoyed the beautiful flowers and captured memorable photos and videos. Special thanks were extended to the Ambassador for this unique opportunity to experience a taste of the Netherlands in Japan.' where id = 'TnPrYyIAYJ2_r5oj1Qf-n';
update content_bodies set title = '【鹿児島県 本格焼酎PR】フランスのシェフ・ソムリエ開発の焼酎専用グラス', description = '鹿児島県と鹿児島県酒造組合が連携し、フランス向けの本格焼酎PR動画を制作しました。この動画には、現地のシェフやソムリエが開発した焼酎専用グラスが登場します。' where id = 'oYEa7J0EFYyRPRSJwUfo-';
update content_bodies set title = 'Authentic Shochu Promotion from Kagoshima Prefecture: Shochu-Specific Glass Developed by French Chef and Sommelier', description = 'Kagoshima Prefecture and the Kagoshima Sake Brewing Association have collaborated to create a promotional video for authentic shochu aimed at the French market. The video features a shochu-specific glass developed by local chefs and sommeliers.' where id = 'eegwvgFlLvtClG04xOSnE';
update content_bodies set title = '＃キバレかごしまプロジェクト～かごしまの花であなたにエールを～', description = '皆さん、鹿児島県の花きは作付面積が全国第3位であることをご存知でしたか？オリエンタルユリやスプレーギク、グラジオラスなど、様々な種類の「かごしまの花」が生産されています。今年度最後の＃キバレ動画では、県内の花き生産者の協力を得て、今年一年頑張ったあなたに贈る「はなむけの言葉」をお届けします。ぜひご覧ください！' where id = '-r4yeDmMQyUTEbZ1kc4QU';
update content_bodies set title = '#Kibare Kagoshima Project - Sending You Support with Kagoshima''s Flowers', description = 'Did you know that Kagoshima Prefecture ranks third in Japan for flower cultivation area? Various types of ''Kagoshima flowers'' such as Oriental lilies, spray chrysanthemums, and gladiolus are produced here. The final #Kibare video of this fiscal year features cooperation from local flower producers, offering ''words of encouragement'' to you for your hard work throughout the year. Please take a look!' where id = 'JIADUiH1TorhlwHyf6gs6';
update content_bodies set title = '世界のトップバーテンダーの目を通した本格焼酎', description = 'この短い動画では、世界的に有名なバーテンダーであるドン・リーが、鹿児島と宮崎で生産される本格焼酎の魅力と焼酎カクテルについて探求します。彼はこの独特なスピリッツの多様性と魅力を強調しています。' where id = 'wAICwGSmd2e_DDjAILaFG';
update content_bodies set title = 'Honkaku Shochu Through the Eyes of One of the Top Bartenders in the World', description = 'In this short video, Don Lee, a renowned bartender, delves into the unique qualities of Honkaku Shochu, a traditional Japanese liquor from Kagoshima and Miyazaki. He also showcases various Shochu cocktails, highlighting the versatility and appeal of this distinctive spirit.' where id = 'WN-BLTLLzWcF6tS5nTsuA';
