update content_bodies set title = '種子島 竹崎海岸', description = 'この動画は、種子島の竹崎海岸について紹介しています。竹崎海岸は美しい自然景観が広がる場所で、訪れる人々にとって魅力的なスポットです。海岸の風景や周辺の環境がどのように描かれているのか、動画を通じてその魅力を感じることができます。' where id = 'xyYELs03U2daYlGrotHQh';
