update content_bodies set title = '加計呂島のガジュマル', description = 'この動画は加計呂島に生育するガジュマルの特徴や魅力について紹介しています。ガジュマルは沖縄地方に多く見られる樹木で、独特の形状と生命力を持っています。加計呂島のガジュマルは特に美しく、観光名所としても知られています。動画では、ガジュマルの生態や周囲の自然環境との関係についても触れられており、視聴者にその魅力を伝える内容となっています。' where id = 'g6UJjkYZ8iqT3nF8FASrP';
