update content_bodies set title = '屋久島', description = 'この動画は屋久島について紹介しています。屋久島は、豊かな自然と独特な生態系を持つ日本の島であり、世界遺産にも登録されています。特に、屋久杉と呼ばれる古代の杉の木が有名で、訪れる人々に感動を与えています。屋久島の美しい風景や多様な動植物についての情報が盛り込まれており、自然愛好者や観光客にとって魅力的な目的地であることが強調されています。' where id = '4KRExpGlshhlsfeU3osYr';
