update content_bodies set title = '枕崎の鰹節', description = 'この動画では、枕崎の鰹節について紹介しています。枕崎は、鰹節の生産地として知られており、その製法や特徴について詳しく解説されています。鰹節は日本料理に欠かせない食材であり、枕崎の鰹節は特に高品質とされています。' where id = 'AA59mFsWFzfawySze9gBr';
