update content_bodies set title = 'Oshima Tsumugi', description = 'This video introduces Oshima Tsumugi, a traditional Japanese textile known for its unique weaving techniques and rich cultural heritage.' where id = 'G694UPiup2tcB18CBtPE9';
update content_bodies set title = '指宿の砂むし温泉', description = 'この動画では、指宿の砂むし温泉について紹介しています。指宿は、独特な砂むし温泉が楽しめる場所で、観光客に人気があります。砂むし温泉は、温かい砂に体を埋めることで、リラックス効果や健康効果が期待できるとされています。指宿の砂むし温泉は、自然の中での癒しの体験を提供し、多くの人々に愛されています。' where id = 'fNnCHPIlTqA9FgT65fJlB';
update content_bodies set title = 'Ibusuki Sand Bath Onsen', description = 'This video introduces the Ibusuki sand bath onsen.' where id = 'BxdtkXRg12Y3Vj6v3GfeG';
update content_bodies set title = '知覧武家屋敷', description = 'この動画は知覧武家屋敷について紹介しています。知覧は、薩摩藩の武士たちが住んでいた場所であり、歴史的な価値が高い地域です。武家屋敷は、当時の武士の生活様式や文化を知ることができる貴重な遺産です。動画では、これらの屋敷の特徴や歴史的背景について詳しく解説されています。' where id = 'BJvbp6e_SlyL2OhHtQSrG';
update content_bodies set title = 'Chiran Samurai Residences', description = 'This video introduces the Chiran Samurai Residences.' where id = 'YPg9f17wJ-sP2GKGXA4qb';
update content_bodies set title = '黒豚しゃぶしゃぶ', description = 'この動画では、黒豚しゃぶしゃぶについて紹介しています。黒豚はその特有の風味と柔らかさで知られており、しゃぶしゃぶのスタイルで楽しむことで、肉の旨味を引き立てます。しゃぶしゃぶは、薄切りの肉を熱い出汁でさっと煮て、タレにつけて食べる日本の伝統的な料理です。この動画では、黒豚しゃぶしゃぶの魅力や調理方法について詳しく解説しています。' where id = 'HNdaAEueUeCbaGTbLhBZU';
