update content_bodies set title = '桜島', description = 'この動画は桜島について紹介しています。桜島は日本の鹿児島県に位置する活火山で、美しい自然景観と豊かな文化を持っています。火山活動が活発で、周辺地域に影響を与えることもありますが、その美しさから観光地としても人気があります。' where id = 'XYJwD1o0WOmuh1-hzTw7a';
