update content_bodies set title = '晩秋の霧島温泉', description = 'この動画では、晩秋の霧島温泉について紹介しています。霧島温泉は、自然に囲まれた美しい温泉地で、晩秋の風景が楽しめる時期に訪れることができます。紅葉が色づく中、温泉に浸かりながら、心身ともにリフレッシュできる魅力があります。' where id = '6ur0yy1RzkgpF8xjROc7N';
