update content_bodies set title = 'いぶすきの菜の花畑', description = 'この動画はいぶすきの菜の花畑について紹介しています。いぶすきの美しい菜の花畑は、春の訪れを感じさせる風景で、多くの観光客を魅了しています。菜の花の鮮やかな黄色が広がる様子は、訪れる人々に癒しを与え、自然の美しさを堪能できる場所です。' where id = 'kIsyqrT-RbynXGBx8rnMU';
