update content_bodies set title = '吉野公園の桜', description = 'この動画は吉野公園の桜について紹介しています。吉野公園は日本の桜の名所として知られ、多くの観光客が訪れます。桜の美しさやその魅力を伝える内容となっており、春の訪れを感じることができるでしょう。' where id = 'tHTPzTVpmf2vKvz6waMrf';
update content_bodies set title = 'Cherry Blossoms at Yoshino Park', description = 'This video introduces the cherry blossoms at Yoshino Park.' where id = 'KthGPJU6rDcOc7iscs8GZ';
update content_bodies set title = '霧島神宮', description = 'この動画は霧島神宮について紹介しています。霧島神宮は日本の神社の一つで、霧島山の美しい自然に囲まれた場所に位置しています。神社は古くから信仰の対象とされ、多くの参拝者が訪れます。霧島神宮の歴史や文化、祭りなどについても触れられており、訪れる価値のあるスポットとして紹介されています。' where id = '_Et4V4DInbpLyCNanqk7O';
update content_bodies set title = 'Kirishima Shrine', description = 'This video introduces Kirishima Shrine.' where id = 'lESDfMmyUZoLrh95Ht0Z_';
update content_bodies set title = '六月灯', description = 'この動画は六月灯について紹介しています。六月灯は、地域の伝統行事として行われる祭りで、特に夏の訪れを祝う重要なイベントです。灯りがともされた提灯が街を彩り、参加者はその美しさを楽しみます。祭りは地域の人々が集まり、交流を深める機会でもあり、文化や伝統を次世代に伝える役割も果たしています。' where id = '5vMJ12SWl0fsqify6wxEK';
