update content_bodies set title = 'Kimura Woodcraft Factory Ltd.', description = 'This video introduces Kimura Woodcraft Factory Ltd.' where id = 'XOE4g31VjUn14reEsWbKb';
update content_bodies set title = '天空の山城 備中松山城をガイドと歩く（高梁市）【岡山観光WEB】', description = '岡山県で話題の体験やツアーを厳選して紹介しています。臨場感あふれる体験レポートや予約、申込みに関する情報が掲載されています。岡山観光に関する詳細は公式サイトをご覧ください。' where id = 'HMYCNM47LHAWdNrCSMbnr';
update content_bodies set title = 'Explore the Sky Castle: Bitchu Matsuyama Castle with a Guide (Takahashi City) - Okayama Tourism WEB', description = 'Discover the latest experiences and tours in Okayama Prefecture! This includes immersive experience reports and information on reservations and applications.' where id = 'ejuOdQkNOy5duQdgAOx91';
update content_bodies set title = '大分県宇佐市観光PR動画', description = '宇佐市の観光公式サイトでは、地域のさまざまな観光名所やアクティビティについての情報が提供されています。岳切渓谷を探索したり、ぶどう狩りを楽しんだり、アフリカンサファリを体験することができます。文化的な名所としては宇佐神宮があり、千財農園や福貴野の滝では自然の美しさを堪能できます。また、麦焼酎や安心院ワイナリーもこの地域の特産品です。両合棚田や御沓橋は注目のランドマークであり、ソニックパーク安心院ではレクリエーション活動が楽しめます。さらに、双葉の里ではユニークな体験ができ、農泊も地元のライフスタイルに浸るための選択肢として提供されています。' where id = 'IHnPHHUActZqm2Kd7igMn';
update content_bodies set title = 'Usa City, Oita Prefecture Tourism PR Video', description = 'The official tourism website of Usa City provides information about various attractions and activities in the area. Visitors can explore Takkiri Ravine, enjoy grape picking, and experience the African Safari. Cultural sites include Usa Jingu, while Senzai Farm and Fukino Waterfall offer natural beauty. The region is also known for its barley shochu and Ajimu Winery. Ryoai Rice Terrace and Mikutsu Bridge are notable landmarks, and Sonicpark Ajimu provides recreational activities. Additionally, Futaba no Sato offers a unique experience, and farm stays are available for those looking to immerse themselves in the local lifestyle.' where id = 'Edaq-v5piLpTsVlylIatt';
update content_bodies set title = 'はじめての農泊【～農泊発祥の地～大分県宇佐市】', description = '農泊とは、農村民泊の略称であり、グリーンツーリズムの中心を成すものです。農泊発祥の地である宇佐市安心院町では、他では味わえない体験や、ここにしかない景色がたくさんあります。「一回泊まれば遠い親戚、十回泊まれば本当の親戚」というキャッチフレーズのもと、まごころ込めて１日１組をお迎えし、受け入れ家庭と共に過ごすことで、心の交流を深め、また帰りたいと思える感動を呼び起こします。田舎のゆっくりとした自然・空間・時間の中で、農泊を体験してみてはいかがでしょうか？' where id = 'O14EaIkKpmUmUe6wC-Bw_';
update content_bodies set title = 'First Experience of Farm Stay: Usa City, Oita Prefecture - The Birthplace of Farm Stay', description = 'Farm stay, abbreviated as ''NOUHAKU'', is a key aspect of green tourism. In Ajimumachi, Usa City, the birthplace of ''NOUHAKU'', visitors can enjoy unique experiences and scenery that cannot be found elsewhere. The catchphrase ''If you stay once, you will be a distant relative; if you stay ten times, you will be a true relative'' reflects the warm hospitality offered to one group per day. This fosters deep emotional connections, encouraging guests to return. Experience ''NOUHAKU'' amidst the slow-paced nature, space, and time of the countryside.' where id = 'Jr_u-VxQZGpXt90ifkcla';
update content_bodies set title = 'はじめての農泊(教育旅行編)【～農泊発祥の地～大分県宇佐市】', description = '農泊とは、農村民泊の略称で、グリーンツーリズムの中心です。農泊発祥の地である宇佐市安心院町では、他では味わえない体験や景色があり、全国から教育旅行や修学旅行で訪れています。「一回泊まれば遠い親戚、十回泊まれば本当の親戚」というキャッチフレーズのもと、まごころ込めて１日１組を迎え、受け入れ家庭と過ごすことで、家庭の温かさや人の優しさに触れ、また帰りたいと思える感動を呼んでいます。田舎のゆっくりとした自然・空間・時間の中で農泊を体験してみてはいかがでしょうか？動画では、宇佐市の特産品「ぶどう」をモチーフにしたキャラクター「ぶどうの女神あじむシャインちゃん」が農泊を紹介しています。' where id = 'uNWXa_h9OV8WtGX6nr0Ye';
update content_bodies set title = 'First Experience of Agricultural Stay (Educational Travel Edition) - Us City, Oita Prefecture, the Birthplace of Agricultural Stay', description = 'Agricultural stay, abbreviated as ''Nohaku'', is a core aspect of green tourism. In Us City, Ajimu Town, where agricultural stays originated, visitors can enjoy unique experiences and landscapes that cannot be found elsewhere. Schools from all over Japan visit for educational trips and school excursions to experience agricultural stays. The catchphrase ''Stay once, and you become a distant relative; stay ten times, and you become a true relative'' reflects the heartfelt welcome extended to one group per day, allowing guests to connect with host families and feel the warmth of home and kindness of people, creating a strong desire to return. Why not experience agricultural stays in the slow-paced nature, space, and time of the countryside? The promotional character, ''Shine-chan, the Goddess of Grapes'', representing the local specialty grapes, introduces agricultural stays in a video.' where id = 'oo21AeaMiqLbU4QkYM9mH';
update content_bodies set title = '「４大グルメ美力のまち」大分県宇佐市～女子旅編～', description = '大分県宇佐市には美味しいグルメが豊富にあり、特におすすめの4つの料理があります。それは「宇佐からあげ」、「大分味一ねぎ」、「安心院すっぽん」、「宇佐どじょう」です。これらの料理は美味しいだけでなく、ヘルシーで美肌に良い栄養素が豊富に含まれているため、特に女性に人気です。宇佐市はその美味しい料理のおかげで、美人が多いと言われています。また、2021年1月14日から3月14日まで「宇佐ん味食べ歩きスタンプラリー」が開催され、参加者は宇佐のグルメを楽しみながらスタンプを集め、最大5万円の商品券を獲得するチャンスがあります。' where id = 'v3FOLqH89mPMi2Y7DJq9y';
update content_bodies set title = 'The Four Major Gourmet Delights of Usa City, Oita Prefecture - Women''s Travel Edition', description = 'Usa City in Oita Prefecture is known for its delicious gourmet offerings, particularly four recommended dishes: ''Usa Karaage'' (fried chicken), ''Oita Ajiichi Negi'' (green onion), ''Anshin-in Suppon'' (soft-shelled turtle), and ''Usa Dojo'' (loach). These dishes are not only tasty but also packed with healthy nutrients that are beneficial for skin health, making them especially appealing to women. It is said that the delicious cuisine of Usa has contributed to the city''s reputation for having many beautiful women. Additionally, the ''Usan Taste Walking Stamp Rally'' is being held from January 14 to March 14, 2021, allowing participants to collect stamps while enjoying the local gourmet and have a chance to win gift certificates worth up to 50,000 yen.' where id = 'b1b6Ub_bZf_EtcEPp_u1a';
update content_bodies set title = '宇佐市お花見', description = '宇佐市のお花見スポットを紹介する映像です。外出が制限されている今、自宅でお花見気分を楽しんでみませんか？肉眼では見えないドローン映像も楽しめます。新型コロナウイルスの影響で油断できない状況が続いていますが、皆で協力して感染防止に努めましょう。宇佐市の新型コロナウイルスに関する最新情報は、リンクから確認できます。また、宇佐市のLINE公式アカウントを利用して最新情報を受け取ることもできます。' where id = 'jGWXJf6u4AnBKfty7XUmY';
update content_bodies set title = 'Usa City Cherry Blossom Viewing', description = 'This video showcases cherry blossom viewing spots in Usa City. In the current situation where outings are limited, why not enjoy the feeling of cherry blossom viewing from home? You can also enjoy drone footage that offers views not visible to the naked eye. Although the situation with COVID-19 remains serious, let’s continue to work together to prevent the spread of the virus. For the latest information on COVID-19 in Usa City, please check the link provided. You can also use the official Usa City LINE account to receive updates.' where id = 'hlfdyGX_oW6WY-w_CZlZ0';
update content_bodies set title = 'うさからくんと宇佐からあげの出会い', description = 'うさからくんはからあげのかぶりものを被ったニワトリの男の子で、「ようこそ宇佐市へ」のサインボードを持ってガイドをしています。休憩中、周囲でからあげを食べる音が聞こえ、みんなが楽しんでいる様子を見て、うさからくんは不思議に思います。実は彼はからあげが苦手ですが、近くの子どもからからあげをもらい、可愛さに負けて受け取ります。食べてみると、その美味しさに感動し、以降は『宇佐からあげ』を世界中に広めるためにPR活動に励むことになります。' where id = 'Zp7jV6cmILABB2w2MfKdg';
update content_bodies set title = 'Usakara-kun and the Encounter with Usa Karaage', description = 'Usakara-kun is a boy chicken wearing a fried chicken costume. He is guiding visitors with a signboard that says ''Welcome to Usa City.'' During a break, he hears the sound of crispy fried chicken being eaten and notices that everyone around him is enjoying it. Usakara-kun feels puzzled because he actually dislikes fried chicken. However, a nearby child offers him some, and despite his initial reluctance, he accepts it because the child is so cute. To his surprise, he finds it delicious and is moved by the taste. From that moment on, Usakara-kun works hard to promote ''Usa Karaage'' so that people all over the world can enjoy it.' where id = 'KB-s-1XRfDuXt_-rJj803';
update content_bodies set title = '宇佐市の一日', description = '宇佐市には、皆さんの想像を超える楽しい体験がたくさんあります。息を飲むような美しい景色を楽しんだり、イチゴやブドウなどのフルーツ狩りを体験したりできます。「見て、感じて、好きになって」というメッセージのもと、特別な一日を宇佐市で過ごしてみませんか？宇佐市へのアクセスや観光情報については、リンクを参考にしてください。' where id = 'P8F2ycoFe09zn_lit6fCU';
update content_bodies set title = 'A day in Usa City', description = 'Usa City offers a variety of enjoyable experiences that go beyond expectations. Visitors can explore breathtaking scenery and indulge in activities like strawberry picking. The city invites everyone to ''See it, feel it, love it'' and encourages people to spend a special day there. For more details on how to reach Usa City or suggestions on how to spend your time, visit their website.' where id = '_ImMG0cNqNCO7tk0s6P0P';
update content_bodies set title = 'Ｉ♥ＵＳＡ ～そこには素敵なシーンがある～', description = '宇佐市の魅力的なシーンを4つのカテゴリに分けて紹介しています。各カテゴリには、宇佐市の特有の美しさや文化、自然の景観などが含まれており、訪れる人々にとって新たな発見や感動を提供する内容となっています。宇佐市の素晴らしさを再認識するための情報が詰まった紹介です。' where id = 'HB1yPm55twtWHo7-doIWo';
update content_bodies set title = 'I ♥ USA - There Are Wonderful Scenes', description = 'This text introduces four categories of wonderful scenes in Usa City.' where id = 'DsGMfw51FP9_eK0OqNKPh';
update content_bodies set title = '志摩地中海村をご紹介(志摩市)｜観光三重｜三重県の観光・旅行情報', description = '志摩地中海村は、地中海の建築様式を模した白壁の建物が並ぶ体験型・滞在型リゾートです。新たにミコノスやメノルカ、アルハンブラをイメージしたエリアが登場し、宿泊専用のアラビックデザインの天然温泉も楽しめます。非日常的な体験ができる志摩地中海村で、異国情緒あふれる街をぜひ訪れてみてください。' where id = 'RYVniuXalNxjOba4elfGE';
update content_bodies set title = 'Introducing Shima Mediterranean Village (Shima City) | Tourism Mie | Mie Prefecture Travel Information', description = 'Shima Mediterranean Village is an experiential and accommodation resort featuring white buildings modeled after Mediterranean architectural styles. Visitors can enjoy new areas inspired by Mykonos, Menorca, and Alhambra, as well as a uniquely designed natural hot spring with Arabic design (for accommodation guests only). Experience the exotic atmosphere of Shima Mediterranean Village.' where id = '2MbSrFSHQR2n_WUx6Rqtp';
update content_bodies set title = '桜花見　千鳥ヶ淵緑道', description = '千鳥ヶ淵緑道は、東京の皇居西側に位置する700メートルの遊歩道で、桜の季節には特に美しい景観を楽しむことができます。約250本の桜の木が千鳥ヶ淵の堀に枝を伸ばし、絵のような風景を作り出します。公園の中央には千鳥ヶ淵ボートハウスがあり、訪問者は水上でボートを借りて楽しむことができます。千鳥ヶ淵という名前は、その形が「千鳥」に似ていることに由来しています。かつては半蔵堀と接続されていましたが、1883年に道路建設のために分断されました。この地域にはソメイヨシノや野生の桜の木が植えられており、東京で最も有名な花見スポットの一つとなっています。アクセスは、都営新宿線と東京メトロ東西線の九段下駅、東京メトロ半蔵門線の半蔵門駅から可能です。' where id = '3HHFXAQPEEkA277gtUbDm';
update content_bodies set title = 'Cherry Blossoms at Chidorigafuchi Ryokudo', description = 'Chidorigafuchi Ryokudo is a 700-meter promenade located on the west side of the Imperial Palace in Tokyo, renowned for its stunning cherry blossoms during the sakura season. Approximately 250 sakura trees extend their branches over the Chidorigafuchi moat, creating a picturesque scene. The Chidorigafuchi Boathouse, situated in the middle of the park, offers boat rentals for visitors to paddle on the water. The name ''Chidorigafuchi'' is derived from its shape resembling ''Chidori.'' Historically, it was connected to Hanzo Moat until it was divided for road construction in 1883. The area features Somei Yoshino and wild cherry trees, making it one of Tokyo''s most famous cherry blossom viewing spots. Access is available via Kudanshita Station on the Toei Shinjuku Line and Metro Tozai Line, as well as Hanzomon Station on the Metro Hanzomon Line.' where id = 'VYjbUQEDuSTJsaR2z9trR';
update content_bodies set title = '東椎屋の滝', description = '日本の滝百選に選ばれた東椎屋の滝は、日光華厳の滝に似ていることから「九州華厳」と称されています。高さ85mの断崖を落下する様子は圧巻で、マイナスイオンも豊富です。また、高貴で美しい名瀑であり、滝つぼから流れ出る清流や渓谷の美しさも特徴です。春には新緑が映え、秋には紅葉が楽しめる素晴らしい景観を誇っています。' where id = 'ZmpK47Dazk4oX6qshi7J_';
update content_bodies set title = 'Higashi Shiuya Falls', description = 'Higashi Shiuya Falls, selected as one of Japan''s top 100 waterfalls, is often referred to as ''Kyushu Kegon'' due to its resemblance to the famous Kegon Falls in Nikko. The waterfall drops from a height of 85 meters, creating a stunning spectacle filled with negative ions. This noble and beautiful waterfall is characterized by the clear stream flowing from its basin and the impressive scenery of the surrounding gorge. Both in spring, when fresh greenery contrasts with the clear water, and in autumn, when the leaves change color, the falls offer breathtaking views.' where id = 'WLzQLOwVDJOehYW3oHlGf';
update content_bodies set title = '富士サファリパーク', description = '富士サファリパークは、富士山の麓に位置する広大な動物園で、主にサファリゾーンとふれあいゾーンの2つのエリアに分かれています。サファリゾーンでは、世界中の動物が生息する7つのゾーンを50分間のドライブで巡ります。自分の車での訪問時は、窓やドアを開けることができず、安全が確保されていますが、ジャングルバスに乗ることで、動物に餌を与える体験も可能です。一方、ふれあいゾーンでは、動物と直接触れ合うことができ、餌を与えたり抱っこしたりすることができるため、子供や動物好きには最適です。詳細は公式ウェブサイトをご覧ください。' where id = 'UA9BKqLQPKbffDyoR43Gt';
update content_bodies set title = 'Fuji Safari Park', description = 'Fuji Safari Park is a large animal park located at the foot of Mt. Fuji, featuring two main zones: the Safari Zone and the Fureai Zone. The Safari Zone offers a 50-minute drive through seven different animal habitats from around the world. Visitors can either drive their own cars, with windows and doors closed for safety, or take a Jungle Bus to feed the animals up close. The Fureai Zone provides a contrasting experience where guests can interact with animals directly, feeding and holding them, making it ideal for children and animal enthusiasts. For more details, visit their website.' where id = 'GcdXdgrgI9QXEMVdxNMAk';
update content_bodies set title = '宇佐市２０１６観光プロモーション動画', description = 'この動画は、宇佐市の観光を促進するために制作された２０１６年のプロモーション動画について紹介しています。宇佐市の魅力や観光スポットを映し出し、訪れる人々にその魅力を伝えることを目的としています。' where id = 'O9GDGT7VfrNZQQDpecwzq';
update content_bodies set title = 'Usa City 2016 Tourism Promotion Video', description = 'This video introduces the Usa City 2016 tourism promotion video.' where id = 'DBMEv9THf2NnV8Mon4B9k';
update content_bodies set title = '宇佐市観光ガイド', description = '宇佐市には観光ガイドがいることをご存知でしょうか？宇佐神宮や石橋、鏝絵などをただ見て回るだけでなく、観光ガイドと一緒に巡ることで、より深く理解することができます。宇佐のガイドは市の歴史だけでなく、さまざまな雑学にも精通しており、楽しい観光体験を提供してくれます。' where id = 'HwIxPtYCENWl9e35xONab';
update content_bodies set title = 'Usa City Tourist Guide', description = 'Did you know that Usa City has tourist guides? Instead of just visiting places like Usa Shrine, stone bridges, and plaster paintings, you can gain a deeper understanding by exploring with a guide. The guides in Usa are knowledgeable not only about the city''s history but also about various trivia, making your sightseeing experience enjoyable.' where id = 'rdN2UUOyuE-5vXPV0xAuo';
update content_bodies set title = '千財バラ園', description = '四日市ICを下り、本耶馬溪に抜ける樋田四日市線に入るとすぐに小倉池があり、その周囲を望む丘陵地の茶畑が千財農園です。ゴールデンウィークに見頃を迎えたフジの花につづき、本年より新たにバラ園がオープンしました。見頃を迎えた約2,000本のバラが色鮮やかに咲き誇り、5,000平方メートルの広大な敷地が気品ある香りに囲まれています。' where id = 'MrnHSMcHfZKAobJthMNAt';
update content_bodies set title = 'Chizai Rose Garden', description = 'Located just off the Yokkaichi IC on the Hida Yokkaichi Line, Chizai Farm is surrounded by tea fields on the hills overlooking Ogura Pond. This year, a new rose garden has opened, following the blooming of wisteria during the Golden Week. Approximately 2,000 roses are in full bloom, filling the expansive 5,000 square meter area with vibrant colors and a delightful fragrance.' where id = '6_tnOJvhVB7K3beFSgXNo';
update content_bodies set title = '根津神社のつつじ祭り', description = '2021年4月の第一週に開催された根津神社のつつじ祭りでは、満開のつつじの美しさを楽しむことができます。この動画では、東京の文京区に位置する根津神社を紹介し、素晴らしい鳥居や伝統的な日本の建築を強調しています。視聴者は、穏やかな春の風景を楽しみ、神社の文化的な意義に浸ることができます。動画は、エンターテインメントと教育を目的としており、マーク・マザーズボーの音楽を使用し、著作権を尊重した内容となっています。視聴者には、季節の美しさをリラックスして楽しむことを促しています。' where id = 'KDy2_9x3cK3wTnkruKEUi';
update content_bodies set title = 'Azalea Festival in Nezu Shrine', description = 'The Azalea Festival at Nezu Shrine, held in the first week of April 2021, showcases the stunning beauty of azalea flowers in full bloom. This video explores the Nezu Shrine located in Bunkyo, Tokyo, highlighting its remarkable Torii gates and traditional Japanese architecture. Viewers are invited to enjoy the serene spring scenery and immerse themselves in the cultural significance of the shrine. The video aims to provide an entertaining and educational experience, featuring music by Mark Mothersbaugh and ensuring that all content respects copyright laws. The creators encourage viewers to relax and appreciate the beauty of the season.' where id = 'U2N6-qNT9xEi--TiX8EGM';
update content_bodies set title = '愛媛で人気の高いグルメスポット14選', description = '愛媛県は、瀬戸内海の新鮮な魚を使った美味しいご当地グルメが豊富な地域です。多くの料理がグルメランキングで上位に入賞しており、今回は愛媛県内のおすすめの名物料理とその料理が楽しめるお店を14選紹介します。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。このチャンネルは、旅行をより楽しくするための情報を提供し、視聴者の旅行体験を豊かにすることを目指しています。' where id = 'jwDuNpNV5mIy5hy0eKlD8';
update content_bodies set title = '14 Popular Gourmet Spots in Ehime', description = 'Ehime Prefecture is known for its delicious local cuisine, particularly fresh seafood from the Seto Inland Sea. This region boasts a variety of tasty dishes that frequently rank highly in gourmet lists. The video presents 14 recommended local specialties and the restaurants where you can enjoy them. If you have any other recommendations not mentioned in the video, feel free to share them in the comments. The channel aims to provide enjoyable travel information, helping viewers to explore and enrich their travel experiences.' where id = 'WrZIvavHleTp64fWRgP5J';
update content_bodies set title = '宇佐神宮の上宮の摂社・末社', description = '宇佐神宮の上宮は権禰宜の高津佳和さんによって案内されます。本殿では八幡大神が広範な神力で守護し、比売大神は学問や芸術、財運、交通安全を司ります。神功皇后は母神として安産や教育を守護しています。上宮までは駐車場から徒歩で10～15分で、体の不自由な方はモノレールが利用可能です。散策を楽しみながらの参拝が推奨されています。摂社・末社には、藤原氏と関係の深い春日神社、道教の神々を祀る北辰神社、海上安全を祈る住吉神社、腹痛の神とされる八子神社、古くからの門の神を祀る善神王神社があります。' where id = 'WPAyQY8rqwlzCTaxP3o_h';
update content_bodies set title = 'Sub-Shrines and Associated Shrines of Usa Jingu''s Upper Shrine', description = 'The Usa Jingu''s upper shrine is guided by Takatsu Yoshikazu, a priest. The main shrine is said to be protected by the powerful deity Hachiman, who oversees various aspects of life, including knowledge, arts, wealth, and safe travels. The goddess Hime is associated with education and childbirth, while Empress Jingu is revered as a mother figure. The upper shrine is a 10-15 minute walk from the parking area, with a monorail available for those with mobility issues. Visitors are encouraged to enjoy a leisurely stroll while visiting the shrine. The sub-shrines include Kasuga Shrine, which is linked to the Fujiwara clan; Hokushin Shrine, associated with Taoist deities; Sumiyoshi Shrine, dedicated to maritime safety; Yakko Shrine, known for its healing powers; and Zejin O Shrine, which houses ancient gate deities.' where id = 'IbPkhhWvRJCcMz9ii9YDH';
update content_bodies set title = '開運祭と四日市の伝統技能体験', description = '四日市伝統技能伝承クラブは、古き良き「四日市」の賑わいを体験してもらうために、体験型観光に力を入れています。歴史散策のほか、四日市に古くから伝わる四日市人形やお数珠づくりなど、開運祭を含む様々なイベントを企画しています。これらの取り組みは観光客だけでなく、地元の子どもたちにも体験してもらうことを目的としています。' where id = 'Qjt5eGjH7T45dgW03wIO_';
update content_bodies set title = 'Kaihunsai Festival and Traditional Skill Experience in Yokkaichi', description = 'The Yokkaichi Traditional Skill Inheritance Club focuses on experiential tourism to allow visitors to experience the vibrant culture of ''Yokkaichi.'' In addition to historical walks, various events are planned, including the creation of Yokkaichi dolls and prayer beads, as part of the Kaihunsai Festival. These activities are designed not only for tourists but also for local children, encouraging them to engage in traditional crafts and cultural experiences.' where id = 'BXpZ2URqmxqsA4uMY10Dh';
update content_bodies set title = '【神奈川観光】日帰り旅行で行きたい！横浜観光スポット15選', description = '神奈川県への旅行や観光の参考として、横浜の歴史と現代が調和したおすすめの観光スポットを15カ所紹介します。この動画に載っていないおすすめがあれば、ぜひコメント欄で教えてください。旅行の達人チャンネルは、観光、移動、宿泊、食事など、旅行をより楽しくする情報を提供しています。旅行を通じて人生を豊かにすることを目指し、視聴者が新しい可能性を発見できるようなきっかけを提供したいと考えています。' where id = 'iNBP4Be5NUx4gqM3A3Gn8';
update content_bodies set title = '15 Must-Visit Yokohama Tourist Spots for a Day Trip in Kanagawa', description = 'This video serves as a guide for those traveling to Kanagawa, showcasing 15 recommended tourist spots in Yokohama where history and modernity beautifully coexist. If you have any additional recommendations not mentioned in the video, please feel free to share them in the comments section. The channel aims to provide valuable travel information to enhance your travel experience, covering various aspects such as sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys.' where id = 't7hH0LpVk0Jesv1s0dFHd';
update content_bodies set title = 'ウサノチカラ～Enjoy Usa Food at home～【ASMR】30秒ver', description = '大分県宇佐市のシティプロモーション動画では、宇佐から届いた段ボールを開封し、有名な麦焼酎や人気のシャインマスカット、宇佐からあげやねぎしゃぶなどのふるさと納税の返礼品が紹介されます。エプロンを着けて調理を始めると、宇佐市のグルメが次々と食卓に並び、麦焼酎を飲みながらからあげやすっぽん鍋、ねぎしゃぶを楽しむ様子が描かれています。最後にはシャインマスカットを頬張り、大満足の表情を見せるシーンで締めくくられ、宇佐の自慢の逸品が紹介されています。' where id = '78ZbSjzoBuX-TRGn5yZKA';
update content_bodies set title = 'Usa''s Power - Enjoy Usa Food at Home - [ASMR] 30-Second Version', description = 'This promotional video from Usa City, Oita Prefecture, showcases a box filled with local delicacies such as famous barley shochu, popular Shine Muscat grapes, and easy-to-cook hometown tax return gifts like Usa fried chicken and negi shabu. As the cooking begins, the delicious flavors of Usa''s cuisine come to life on the dining table. Enjoying the meal with barley shochu, the video highlights dishes like fried chicken, soft-shelled turtle hot pot, and negi shabu, culminating in the delightful taste of Shine Muscat grapes. This video proudly presents the culinary treasures of Usa.' where id = 'd80SQA5oGAzD0Pk3pklM2';
update content_bodies set title = '米子人気グルメ10選｜多彩なグルメスポット紹介', description = 'この動画では、鳥取県米子市の人気グルメスポット10選を紹介しています。旅行や観光の参考にしていただければ幸いです。動画に紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行をより楽しくする情報を提供しています。旅行を通じて人生を豊かにすることを目指しており、多くの人が新しい可能性を発見するきっかけとなることを願っています。' where id = '3JVZc1CM9AyxNkf0M9qg5';
update content_bodies set title = 'Top 10 Popular Gourmet Spots in Yonago, Tottori', description = 'This video introduces ten popular gourmet spots in Yonago, Tottori, perfect for those planning a trip or sightseeing in the area. If you have any recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys.' where id = 'M10S89QsXNlahXf4WIcuC';
update content_bodies set title = '【兵庫】神戸の人気観光スポット15選【女子旅にも人気な神戸】', description = '兵庫県への旅行や観光の参考として、神戸の人気観光スポットを厳選して15か所紹介する動画です。動画に紹介されていないおすすめスポットがあれば、コメント欄でシェアしてください。旅行の達人チャンネルは、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行を通じて人生を豊かにすることを目指しています。メンバーは旅行を通じて新しい可能性を発見することを奨励しており、公式SNSアカウントをフォローすることで、さらに多くの旅行情報を得ることができます。' where id = 'msMEtOOk5uK6GNfHmebc8';
update content_bodies set title = '15 Popular Tourist Spots in Kobe, Hyogo: Perfect for Girls'' Trips', description = 'This video serves as a guide for those traveling to Hyogo Prefecture, showcasing 15 selected popular tourist spots in Kobe. If you have any recommendations that are not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to provide enjoyable travel information, covering various aspects such as sightseeing, transportation, accommodation, and dining. The team believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys. For more travel tips and updates, you can follow their official social media accounts.' where id = 'oHSMRZjv4zq5hB19h3uaW';
update content_bodies set title = '【福島土産】迷ったらこれ！福島の喜ばれるお土産15選', description = '福島県を訪れる旅行者に向けて、和菓子、洋菓子、ご当地グルメの3種類に絞ったおすすめのお土産15選を紹介する動画です。動画に紹介されていないおすすめがあれば、コメント欄でシェアしてください。旅行の達人チャンネルは、旅行をより楽しくするための情報を提供し、視聴者が新しい可能性を発見できるよう促しています。' where id = 'n6Gv01P9i8fzheACGFqRB';
update content_bodies set title = 'Fukushima Souvenirs: 15 Recommended Gifts', description = 'This video serves as a guide for travelers visiting Fukushima Prefecture, showcasing 15 recommended souvenirs categorized into three types: traditional Japanese sweets, Western-style confections, and local gourmet foods. If you have any other suggestions not mentioned in the video, feel free to share them in the comments. The channel aims to provide valuable travel information to enhance your experience, encouraging viewers to explore and discover new possibilities through travel.' where id = 'Q0eKr009hRGiyBf9hAgXc';
update content_bodies set title = '【岩手 観光】岩手のオススメ観光スポット10選', description = '岩手県への旅行を計画している方に向けて、自然を満喫できる観光スポットを10カ所紹介しています。どのスポットもリラックスできる環境が整っており、家族や友人と一緒に訪れるのに最適です。また、旅行の達人チャンネルでは、観光地や宿泊、食事に関する情報を提供し、旅行をより楽しくするためのヒントを発信しています。旅行を通じて新しい自分を発見し、人生を豊かにすることを目指しています。' where id = 'acDkfpWtKx-AD5JIM2orG';
update content_bodies set title = 'Recommended Tourist Spots in Iwate: Top 10', description = 'This guide provides recommendations for travelers visiting Iwate Prefecture, highlighting ten must-see tourist spots that allow visitors to enjoy the region''s natural beauty. Each location offers a relaxing atmosphere, making them perfect for family outings or trips with close friends. The video also encourages viewers to subscribe to the channel for more travel tips and information, aiming to enhance the travel experience by sharing insights on various aspects of travel, including sightseeing, accommodation, and dining. The channel''s mission is to enrich lives through travel, helping individuals discover new possibilities and experiences.' where id = 'keUp4h9x_HBrKYt8-v1nX';
update content_bodies set title = '【岩手 観光】岩手で人気の宿15選', description = '岩手県への旅行や観光に役立つ情報を提供します。岩手県は宮沢賢治の出身地として知られ、宮沢賢治記念館でその足跡を辿ることができます。また、平泉には国宝の中尊寺金色堂を含む世界遺産があり、歴史や文化に触れることができます。美しい観光スポットや美味しいグルメ、素晴らしい旅館やホテルが揃う岩手県で、心から癒される人気の宿を15軒ご紹介します。' where id = 'vxs9qVTUJnj3UJIErjDmo';
update content_bodies set title = 'Top 15 Popular Accommodations in Iwate', description = 'This guide is perfect for those planning a trip to Iwate Prefecture. Known as the birthplace of Kenji Miyazawa, visitors can explore his legacy at the Miyazawa Kenji Memorial Museum. Additionally, Hiraizumi is home to the World Heritage Site of Chuson-ji Temple and its Golden Hall, offering a deep dive into Japan''s history and culture. Iwate is blessed with numerous beautiful tourist spots, delicious cuisine, and a variety of excellent inns and hotels. In this article, we present 15 popular accommodations in Iwate that promise to provide a truly relaxing experience.' where id = 'MSrfq0H3x2zfRkn4OSuN0';
update content_bodies set title = 'ウサノチカラ～Enjoy Usa Food at home～【ASMR】', description = '大分県宇佐市のシティプロモーション動画では、宇佐の地から届いた段ボールを開封し、有名な麦焼酎や人気のシャインマスカット、宇佐からあげやねぎしゃぶなどのふるさと納税の返礼品が紹介されます。エプロンを着けて調理を始めると、宇佐市のグルメが次々と食卓に並び、麦焼酎を飲みながらからあげやすっぽん鍋、ねぎしゃぶを楽しむ様子が描かれています。最後にはシャインマスカットを頬張り、大満足の表情を見せるホスト。この動画は、宇佐の自慢の逸品を紹介し、他にも魅力的な返礼品が多数用意されていることを伝えています。' where id = 'fIeZHnnBQr9gS0vYKo_2O';
update content_bodies set title = 'Usa''s Power - Enjoy Usa Food at Home - [ASMR]', description = 'This promotional video from Usa City, Oita Prefecture, showcases a box filled with local delicacies. Inside, viewers find famous barley shochu, popular Shine Muscat grapes, and easy-to-cook hometown tax return gifts like Usa fried chicken and negi shabu. As the host dons an apron and begins cooking, the delicious flavors of Usa City come to life on the dining table. Enjoying the meal with barley shochu, the host savors fried chicken, soft-shelled turtle hot pot, and negi shabu, culminating in a satisfying bite of the beloved Shine Muscat. This video proudly presents the exceptional offerings of Usa. Additionally, there are many other attractive return gifts available.' where id = 'xfGVwHB0i7XZPlm-1XT08';
update content_bodies set title = '世界かんがい施設遺産 宇佐のかんがい用水群(平田井路・広瀬井路）', description = '令和3年11月26日、モロッコのマラケシュで開催された第72回国際かんがい排水委員会理事会において、「宇佐のかんがい用水群」（平田井路・広瀬井路）が世界かんがい施設遺産に登録されました。この登録は市と宇佐土地改良区が共同で申請したもので、日本国内では44番目、大分県内では初の登録となります。国際機関による認定は、施設の保全だけでなく、地域振興や情報発信にも寄与します。今後は、両かんがいシステムの検証を続けながら、地域活動に積極的に関与し、観光資源や教育資源として活用・発展させていく予定です。' where id = 'eV77NV02Q1cdPq1k5ypSf';
update content_bodies set title = 'World Heritage Certification of Irrigation: The Usa Irrigation System', description = 'On November 26, 2022, the Usa Irrigation System, which includes the Hirata and Hirose irrigation systems, was registered as a World Heritage Irrigation Structure during the 72nd International Executive Council meeting of the International Commission on Irrigation & Drainage in Marrakesh, Morocco. This registration was a joint application by the city and the Usa Land Improvement District, marking it as the 44th registration in Japan and the first in Oita Prefecture. The certification by an international organization will not only aid in the preservation of these facilities but also contribute to regional revitalization and information dissemination. Moving forward, there will be active engagement in local activities, utilizing these irrigation systems as resources for tourism and education.' where id = 'J9YR7gNO61Tz--svxqH_d';
update content_bodies set title = '【パワースポット巡り】 神社仏閣で金運もUP！山形観光でエネルギーを蓄える！', description = '山形県への旅行や観光に役立つ情報を提供します。山形には銀山温泉や蔵王温泉といった有名な温泉地があり、さらに多くのパワースポットが存在します。今回は運気が上がるとされる山形のおすすめパワースポットを15カ所ご紹介します。また、旅行の達人チャンネルでは、旅行をより楽しくするための情報を発信し、旅行を通じて新しい可能性を見つける手助けをしています。' where id = 'xMK1YomCGSnkFEFI4_Vcn';
update content_bodies set title = 'Power Spot Tour: Boost Your Fortune at Shrines and Temples! Recharge Your Energy with Yamagata Tourism!', description = 'This guide is perfect for your trip to Yamagata Prefecture, known for its famous hot springs like Ginzan Onsen and Zao Onsen, as well as numerous power spots. We present 15 recommended power spots in Yamagata that are said to surely enhance your luck. The channel also offers insights into various travel information, aiming to enrich your travel experiences and help you discover new possibilities through travel.' where id = 'JUvRvgRzU68LIoRKx-Xm3';
