update content_bodies set title = 'Introduction to Usa City DC Related Events Part 3', description = 'This article introduces events related to Usa City as part of the ''Fukuoka-Oita Destination Campaign'' starting in April 2024, presented by the Usa City Tourism Ambassador.' where id = 'vEWDSnq8SQugxJDHcVztJ';
update content_bodies set title = '宇佐市DC関連イベント紹介第4弾', description = '2024年4月から開催中の「福岡・大分デスティネーションキャンペーン」に関連する宇佐市のイベントを、宇佐市観光アンバサダーが紹介します。' where id = 'L0rJtFGxFMo6HpxHL33wz';
update content_bodies set title = 'Introduction to Usa City DC Related Events Vol. 4', description = 'This article introduces events related to Usa City as part of the ''Fukuoka-Oita Destination Campaign'' that started in April 2024, presented by the Usa City Tourism Ambassador.' where id = 'Yc5bmqP22hMXuxDusuHRp';
update content_bodies set title = '宇佐高生による宇佐市の魅力紹介動画', description = '宇佐高等学校では、総合的な探求の時間において、創造力を活かした課題解決手法「デザインシンキング」を学んでいます。今回、宇佐地域の魅力を伝える動画を作成しました。14本のショート動画を1本にまとめて見やすくしており、学生たちの個性や郷土愛があふれる内容となっています。ぜひお楽しみください。' where id = '7K3gBKaZKRycl8_5NyFcM';
update content_bodies set title = 'Usa High School Students Introduce the Charm of Usa City', description = 'At Usa High School, students are learning about ''design thinking,'' a problem-solving method that utilizes creativity, during their comprehensive inquiry time. They have created a video to showcase the attractions of the Usa region. The video compiles 14 short clips into one cohesive presentation, making it easy to watch. Enjoy the videos that reflect the students'' individuality and love for their hometown.' where id = 'lDmU8-smOqui5wg1T2uuB';
update content_bodies set title = '【兵庫 観光】姫路で訪問したい観光スポット15選', description = '兵庫県の姫路市には、世界遺産の「姫路城」をはじめとする多くの観光スポットがあります。姫路城を目当てに国内外から多くの観光客が訪れていますが、他にも魅力的なスポットがたくさん存在します。今回は、姫路を訪れた際にぜひ立ち寄りたい観光地を15カ所紹介します。動画で紹介されていないおすすめの場所があれば、コメント欄で教えてください。このチャンネルは、旅行をより楽しくするための情報を提供し、旅行を通じて新しい可能性を発見し、人生を豊かにする手助けを目指しています。' where id = '0VyfPcIFvM4ibmEhvqSNE';
update content_bodies set title = '15 Must-Visit Tourist Spots in Himeji, Hyogo', description = 'Himeji City in Hyogo Prefecture is home to numerous tourist attractions, including the world-renowned Himeji Castle. While many visitors flock to see this beautiful castle, there are many other wonderful spots to explore. This video presents 15 must-visit tourist destinations in Himeji. If you have any recommendations not mentioned in the video, please share them in the comments. The channel aims to provide valuable travel information to enhance your travel experience, helping you discover new possibilities and enrich your life through travel.' where id = 'IYVousEswjK_gbiwVMazC';
update content_bodies set title = '【兵庫 観光】 神戸のおすすめパワースポット15選', description = '兵庫県への旅行や観光を考えている方に向けて、神戸にあるパワースポットを15カ所紹介する動画です。動画で紹介されていないおすすめのスポットがあれば、ぜひコメント欄でシェアしてください。旅行の達人チャンネルは、観光、移動、宿泊、食事など、旅行をより楽しくするための情報を提供しています。旅行を通じて人生を豊かにすることを目指し、視聴者が新しい可能性を発見できるようなきっかけを提供したいと考えています。' where id = 'Cckhz-pVsW0jZ581VvrAh';
update content_bodies set title = '15 Recommended Power Spots in Kobe, Hyogo', description = 'This video serves as a guide for those traveling to or sightseeing in Hyogo Prefecture, specifically highlighting 15 power spots in Kobe. If you have any recommendations that are not mentioned in the video, please feel free to share them in the comments. The channel aims to provide valuable travel information to enhance your travel experience, covering various aspects such as sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys.' where id = 'ctiiMnhg9ljS5UxEpHG1v';
update content_bodies set title = '横浜でインスタ映えスポット15選', description = '神奈川県横浜市の観光スポットを15カ所紹介するガイドです。横浜はエキゾチックな雰囲気や最新の高層ビル、豪華客船が停泊する横浜港、美しい夜景の見えるみなとみらいエリア、日本最大の中華街である元町中華街、レトロな洋館が並ぶ山手エリアなど、多彩な観光地が魅力です。それぞれのスポットには素敵な撮影スポットがあり、インスタ映えする写真が撮れます。この動画で紹介されていないおすすめの場所があれば、ぜひコメント欄で教えてください。旅行の達人チャンネルは、旅行をより楽しくする情報を提供することを目的としています。' where id = 'RjvXTphGPjQBATu7Ko-tA';
update content_bodies set title = '15 Instagrammable Spots in Yokohama, Kanagawa', description = 'This guide highlights 15 Instagram-worthy locations in Yokohama, Kanagawa, perfect for travelers and tourists. Yokohama is known for its exotic atmosphere, modern skyscrapers, luxurious cruise ships at the port, beautiful night views in the Minato Mirai area, Japan''s largest Chinatown in Motomachi, and retro Western-style buildings in the Yamate area. Each of these spots offers unique photo opportunities. If you have any recommendations not mentioned in this video, please share them in the comments. The channel aims to provide enjoyable travel information to enhance your travel experiences.' where id = '932vybmPI0n68xaGvjlfG';
update content_bodies set title = '旅する宇佐 ダイジェスト編', description = '宇佐市の魅力が詰まったダイジェスト版です。観光や文化、自然など、宇佐市の様々な魅力を短くまとめています。ぜひご覧いただき、宇佐市の素晴らしさを感じてください。' where id = 'J7wrrUr4M-2azyUK0zTZ4';
update content_bodies set title = 'Traveling Usa: Digest Edition', description = 'This is a digest version that encapsulates the charm of Usa City. Please take a look.' where id = 'qiTcrw6UxxvULO59Ltsby';
update content_bodies set title = 'ご当地ソング「宇佐浪漫」ＭＶ完成', description = 'ご当地ソング「宇佐浪漫」のミュージックビデオが完成し、関係者から市にDVDが寄贈されました。4月からは大手通信カラオケの一部機種での配信も始まります。この映像には宇佐市や宇佐神宮の魅力が詰まっており、ぜひご視聴いただきたいです。歌手は岡部浩和、詞曲はあとだ義、モデルは宇佐市観光アンバサダーの永松佐理、ディレクターは森孝良です。' where id = 'gC4Y-vM5M0FymgaYW9WZu';
update content_bodies set title = 'Completion of the Local Song ''Usa Roman'' MV', description = 'The music video for the beloved local song ''Usa Roman'' has been completed, and a DVD has been donated to the city by related parties. Starting in April, it will also be available for streaming on major karaoke systems (on select models). The video is filled with the charm of Usa City and Usa Shrine. Please take a moment to watch it. The singer is Hirokazu Okabe, with lyrics and music by Yoshikazu Atoda, featuring model Sari Nagamatsu (Usa City Tourism Ambassador) and directed by Takayoshi Mori.' where id = 'xCA4SXQb20C31Qiss6pwx';
update content_bodies set title = '山形県民も絶賛の人気グルメスポット10選', description = '山形県への旅行や観光に役立つ情報を提供します。地元の人々にも人気のあるグルメスポットが多数あり、特におすすめの場所を紹介しています。ランチやディナーに適したスポットが揃っており、山形県での食事の参考にしていただけます。地元の美味しい料理を楽しむために、ぜひ訪れてみてください。' where id = '04bfMHStHSExIu7MVNVpK';
update content_bodies set title = 'Top 10 Popular Gourmet Spots in Yamagata Prefecture Praised by Locals', description = 'This guide is perfect for those traveling to Yamagata Prefecture, showcasing a variety of popular gourmet spots favored by locals. The article highlights recommended places for both lunch and dinner, making it a useful reference for dining in Yamagata. Additionally, it encourages readers to explore the local cuisine and enjoy the culinary delights the region has to offer.' where id = 'owXSp2c71vPlr0bewNOLP';
update content_bodies set title = '宇佐神宮御鎮座1300年PR動画が完成しました！', description = '宇佐神宮御鎮座1300年を祝うPR動画が完成しました。今後、各地でイベントが開催される予定ですので、ぜひお越しください。詳細については、下記のリンクをご確認ください。' where id = 'qypTyPeaIs5_O9_RuC4CJ';
update content_bodies set title = 'Completion of the PR Video for the 1300th Anniversary of Usa Jingu Shrine', description = 'A PR video has been created to commemorate the 1300th anniversary of Usa Jingu Shrine. There will be various events held in different locations, and we encourage everyone to attend. For more details, please check the link below.' where id = '0lDU3RzLhNcdWk9czxyHl';
update content_bodies set title = '宇佐神宮御鎮座1300年PR動画（ロングバージョン）', description = '宇佐神宮の御鎮座1300年を祝うPR動画が作成されました。今後、各地でイベントが開催される予定ですので、ぜひお越しください。詳細については、こちらをご確認ください。https://www.city.usa.oita.jp/tourist/index.html' where id = '8EbxFaEwSBFZa5JEh0CC6';
update content_bodies set title = 'PR Video for 1300th Anniversary of Usa Jingu Shrine (Long Version)', description = 'A PR video has been created to celebrate the 1300th anniversary of Usa Jingu Shrine. Various events will be held in different locations, and we invite you to join us. For more details, please check here: https://www.city.usa.oita.jp/tourist/index.html' where id = 'G70FFytj1cFPRR-i3sKHw';
update content_bodies set title = '山形でオススメのお土産10選', description = '山形県には多様なお土産があり、特におすすめの10品を紹介します。これらは旅行のお土産としてだけでなく、自宅用や贈り物にも適しています。食べ物を選ぶ際は、海外への持ち込みに制限がある場合があるため、購入前にお店や検疫に確認することをお勧めします。山形県のお土産選びの参考にしてください。' where id = 'noHZxzCCF_Nwt3391xq9e';
update content_bodies set title = 'Recommended Souvenirs from Yamagata: Top 10 Picks', description = 'This guide introduces ten recommended souvenirs from Yamagata Prefecture, perfect for travelers and tourists. These items are not only great as souvenirs but also suitable for personal use or as gifts. When selecting food items, be aware that there may be restrictions on bringing them into other countries. It''s advisable to check with the store or customs before making a purchase to ensure compliance with international travel regulations.' where id = 'u2XDWwvJnTa8RkzZ10lh6';
update content_bodies set title = '和歌山県紀美野町「日本一の『ない』を提供します！」', description = '和歌山県の紀美野町は、現代的な便利さがないことが特徴の町です。電車もスーパーマーケットもネイルサロンもなく、シンプルさを大切にしたユニークな目的地です。「日本一の『ない』を提供します！」というスローガンで町をPRしています。訪れる人々は、ドゥーシェルベーカリー・テラスや紀美の家、のかみふれあい公園など、さまざまな地元の観光スポットを楽しむことができます。都市生活からの静かな逃避を求める人々にとって、紀美野町は欠如の美しさを強調した独特の体験を提供します。' where id = '4vXBq-BivP2o8wsDPRXkO';
update content_bodies set title = 'Kimino Town Wakayama Prefecture "We offer the best No''s, Nothings and Nevers… in Japan!"', description = 'Kimino Town, located in Wakayama Prefecture, is characterized by its lack of modern amenities. There are no trains, supermarkets, or nail salons, making it a unique destination that embraces simplicity. The town promotes itself with the slogan, "We offer the best No''s, Nothings and Nevers in Japan!" Visitors can explore various local attractions, including Dooshel Bakery Terrace, Kiminōka, Nokami Fureai Park, and more. For those seeking a tranquil escape from urban life, Kimino Town offers a distinctive experience that highlights the beauty of absence.' where id = '1Y5ol3no6cVUD7ax2ot-D';
update content_bodies set title = '足湯めぐり', description = '白浜町内にある足湯を存分に楽しんでください。足先から体全体を癒やすことができます。' where id = '5KUJTLosLmyTHfAt9Kqgg';
update content_bodies set title = 'Foot Bath Tour', description = 'Enjoy the foot baths located in Shirahama Town to your heart''s content! Heal your body starting from your feet!' where id = 'Jh2a7cAb-GYznan9z_KSd';
update content_bodies set title = '崎の湯', description = '崎の湯は、万葉の昔から「湯崎七湯」の中で唯一残っている歴史ある温泉です。雄大な太平洋が間近に迫る露天風呂では、湯船から海がほぼ一体となり、岩に打ち寄せる波を感じながら入浴できます。温泉には硫黄と潮の香りが漂い、波の音や太平洋を渡る船の姿も楽しめます。お湯だけでなく、大自然にどっぷり浸かった開放感を味わえる特別な体験が待っています。' where id = 'p9g-7YHakVbYNeiPI2bQB';
update content_bodies set title = 'Saki no Yu', description = 'Saki no Yu is a historic hot spring that has remained since ancient times as the only one of the ''Yuzaki Seven Springs.'' It features an open-air bath that is in close proximity to the majestic Pacific Ocean. While bathing, guests can feel the waves crashing against the rocks, creating a unique experience where the sea and the bath almost merge. The air is filled with the scents of sulfur and sea breeze, accompanied by the sound of waves and ships slowly crossing the Pacific. This hot spring offers not just a soak in the water, but also a deep sense of liberation immersed in the beauty of nature.' where id = 'QHvOj8-A4NUUlX-TQxkgA';
update content_bodies set title = '新潟観光/グルメ 新発田市の定番めぐり！', description = 'この動画は新潟県新発田市を訪れる旅行者向けのガイドです。観光スポットや地元のグルメを紹介し、充実した旅行を楽しむための情報を提供しています。視聴者には、コメント欄で自分のおすすめをシェアするよう促しています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。運営チームは、旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見し、旅を楽しむことを願っています。' where id = '_pXqI607Koxee5PPQDysg';
update content_bodies set title = 'Exploring Niigata: 7 Must-Visit Spots in Shibata City', description = 'This video serves as a guide for travelers interested in visiting Shibata City in Niigata Prefecture. It highlights popular tourist spots and local cuisine that are essential for a fulfilling trip. Viewers are encouraged to share their own recommendations in the comments section. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and hopes to inspire viewers to discover new possibilities and enjoy their journeys. For more information, viewers can follow the channel on various social media platforms.' where id = 'aaD7r5TjABt9FD2ckBJ8q';
update content_bodies set title = 'GEO MIRACLE KOBE（ロングバージョン 日本語字幕）', description = 'この動画は、日本の神戸の美しさと独自の特徴を紹介しています。神戸のさまざまな観光名所や文化的要素、そして素晴らしい風景を強調し、神戸が特別な目的地である理由を伝えています。ロングバージョンでは、視聴者が街の景色や音に浸ることができ、神戸の魅力を包括的に見ることができます。' where id = 'oRaWs1BhfNgWQbMswT0in';
update content_bodies set title = 'GEO MIRACLE KOBE (Long ver. with Japanese subtitles)', description = 'This video showcases the beauty and unique features of Kobe, Japan. It highlights various attractions, cultural elements, and the stunning landscapes that make Kobe a remarkable destination. The long version allows viewers to immerse themselves in the sights and sounds of the city, providing a comprehensive look at what makes Kobe special.' where id = 'mBZk9ngvHiQ47qX1_dHfR';
update content_bodies set title = 'GEO MIRACLE KOBE～母なる六甲山～', description = 'このコンテンツは、神戸の美しさと魅力を紹介し、特に六甲山に焦点を当てています。自然の風景や文化的な重要性、地域で楽しめるさまざまなアクティビティが強調されています。ウェブサイトでは、神戸のユニークな魅力を探求したい訪問者のための追加情報が提供されています。' where id = 'iIAVtYsFg65BjoI9CLfAB';
update content_bodies set title = 'GEO MIRACLE KOBE～Mother Mt.Rokko～', description = 'This content features the beauty and attractions of Kobe, particularly focusing on Mount Rokko. It highlights the natural scenery, cultural significance, and various activities available in the area. The website provides additional information for visitors looking to explore Kobe''s unique offerings.' where id = 'KkDy3MfOmCO8ClVaKRLKV';
update content_bodies set title = 'GEO MIRACLE KOBE ～Water and Sake～', description = 'このコンテンツは、神戸における水と酒の独特な関係に焦点を当てており、地域の文化遺産やこれらの要素が地元の伝統において持つ重要性を強調しています。詳細については、提供されたリンクを訪れてください。' where id = 'LY6ZpAkgSqc0ryUsLIiSZ';
update content_bodies set title = 'GEO MIRACLE KOBE ～Water and Sake～', description = 'This content focuses on the unique relationship between water and sake in Kobe, highlighting the city''s rich cultural heritage and the significance of these elements in local traditions. For more information, visit the provided link.' where id = '1FmLDnDx0g-WmM8LGWTP_';
update content_bodies set title = '高知県 土佐の匠 「尾戸焼」', description = '江戸時代から続く「尾戸焼」の継承者である谷信一郎さんが、あしもとの自然を活かしたものづくりへの思いを語ります。彼の作品は、地域の自然を大切にしながら、伝統を守り続ける姿勢が反映されています。尾戸焼は、長い歴史を持つ陶芸であり、谷さんの情熱がその技術と美しさを次世代に引き継いでいます。' where id = 't8AurSXb7scTI0e-KSbxc';
update content_bodies set title = 'Tosa Craftsman: Odo-yaki', description = 'Shinichiro Tani, the successor of Odo-yaki, which has been passed down since the Edo period, shares his thoughts on creating products that utilize the natural environment around him.' where id = 'rXzvbTinD4qYw18l6DZzr';
update content_bodies set title = 'くえ料理', description = 'クエは本州中部以南に生息するハタ科の魚で、成魚は1m、30～50kgにもなります。荒磯を悠然と泳ぐ孤高の巨大魚であり、水揚げが少なく「幻の魚」と呼ばれています。そのグロテスクな見かけとは裏腹に、脂の乗った美しい白身は上品で深みのある味わいを持っています。また、ゼラチン質がたっぷり含まれた皮やアラの味は、一度食べると忘れられないと言われています。' where id = '5iG6Rioh1CMJItToWLQiI';
update content_bodies set title = 'Kue Cuisine', description = 'Kue is a fish belonging to the grouper family, found in the waters from central Honshu to the south. Adult kue can grow up to 1 meter long and weigh between 30 to 50 kg. Known as the ''phantom fish'' due to its rarity, this solitary giant swims gracefully in rocky coastal areas. Despite its grotesque appearance, kue has a beautiful white flesh rich in fat, offering a refined and deep flavor. The taste of its gelatinous skin and bones is said to be unforgettable after just one bite.' where id = 'dd-4UN6Opyd1RYL0oAqJ6';
update content_bodies set title = 'とれとれ市場 後編', description = '西日本最大級の海鮮マーケット「とれとれ市場」では、日本全国の新鮮なお魚をその場で楽しむことができます。また、和歌山のお土産をショッピングしたり、楽しいBBQコーナーも用意されています。非常に広大な市場であり、1日では回りきれないほどの充実した内容が揃っており、訪れる人々に大満足の体験を提供しています。' where id = 'XGF7rOXUSb_oP5xq6Ljb8';
update content_bodies set title = 'Toretore Market Part 2', description = 'Toretore Market is one of the largest seafood markets in Western Japan! Visitors can enjoy fresh seafood from all over Japan, shop for souvenirs from Wakayama, and even take part in a fun BBQ corner. The market is so extensive that it cannot be fully explored in just one day, ensuring a satisfying experience for all.' where id = 'Q74ffbJ0JG5V-QWYUg-ju';
update content_bodies set title = 'とれとれ市場 前編', description = '西日本最大級の海鮮マーケット「とれとれ市場」では、日本全国の新鮮なお魚をその場で楽しむことができます。また、和歌山のお土産をショッピングしたり、楽しいBBQコーナーも用意されています。多彩なアクティビティが揃っており、たった一日では回りきれないほどの充実した市場です。' where id = 'e_MKCkglbx7l4w4rdLbHb';
update content_bodies set title = 'Toretore Market Part 1', description = 'Toretore Market is one of the largest seafood markets in Western Japan! Visitors can enjoy fresh seafood from all over Japan, shop for souvenirs from Wakayama, and even take part in a fun BBQ corner. This market offers so much that it cannot be fully explored in just one day, ensuring a satisfying experience for all.' where id = 'KrFLNA-44p93b8uQCpBqP';
update content_bodies set title = 'ウツボ料理', description = '「うつぼ」は、そのグロテスクな顔形と小骨が多いため、一般的にはあまり知られていない魚です。しかし、その美しい白身は癖がなく淡白で、表皮にはゼラチン質やコラーゲンが豊富に含まれており、料理すると「これがうつぼか！」と驚くほどの美味しさを持っています。料理方法も多彩で、うす造り、タタキ、しゃぶしゃぶ鍋、すき焼き、唐揚げ、照焼きなど、様々なスタイルで楽しむことができます。' where id = 'sTuOLBsiHe0B5ZlivUhcp';
update content_bodies set title = 'Eel Cuisine', description = 'The eel, known for its grotesque appearance and numerous small bones, is not commonly familiar to many. However, its beautiful white flesh is mild and delicate, rich in gelatin and collagen, making it surprisingly delicious when cooked. Dishes such as sashimi, tataki, shabu-shabu, sukiyaki, fried eel, and teriyaki showcase the versatility of eel in cooking.' where id = 'M65HQ-UVfyqY-ckQqDe5v';
update content_bodies set title = '見栄サミット第2弾（リモート会議ver） 三話「歴史を語るインフルエンサー／伊賀」 #三重の観光PR動画', description = '三重県の５つのエリアを国に見立てたショートムービー「見栄サミット」が、リモート会議形式で帰ってきました。第３話は伊賀編で、歴史をテーマにしたリモート会議で、インフルエンサーが伊賀の魅力を語ります。多くのフォロワーを持つインフルエンサーは、自身のインスタ映えする写真を見せながら、伊賀の歴史をプレゼンテーションします。登場するスポットには、俳聖殿、斎宮、伊賀の地酒の酒蔵、おかげ横丁、伝統工芸品の伊賀くみひもや伊勢型紙、伊賀焼、ユネスコ無形文化遺産の上野天神祭などが含まれています。' where id = 'F64Ga_FPzegG8JSK3mtE6';
update content_bodies set title = 'Mie Summit Vol.2 (Remote Meeting Version) Episode 3: ''Influencer Discussing History / Iga'' #Mie Tourism PR Video', description = 'The short movie ''Mie Summit'' returns as a ''remote meeting,'' where leaders from five areas of Mie Prefecture, each imagined as a separate country, gather to boast about their local attractions. Episode 3 focuses on Iga, featuring an influencer who shares the historical charm of the area during the remote conference. The influencer reveals their significant following and presents Instagram-worthy photos while discussing Iga''s rich history. Key locations highlighted include the Haiseiden, Saiku, local sake breweries, Okage Yokocho, traditional crafts like Iga Kumihimo and Ise Katagami, Iga-yaki pottery, and the Ueno Tenjin Festival, recognized as a UNESCO Intangible Cultural Heritage.' where id = 'i3GREECflICh4L_Cpmvba';
update content_bodies set title = 'マグロ解体ショー　フィッシャーマンズワーフ白浜', description = '南紀白浜にある漁師直営の海鮮市場、フィッシャーマンズワーフ白浜で『冬のお魚祭り The まぐろ』が開催され、まぐろの解体ショーが行われました。この解体ショーは至近距離から見ることができ、非常に迫力があります。フィッシャーマンズワーフ白浜では、季節ごとにお魚祭りを開催しており、施設やイベントの詳細は公式ホームページで確認できます。' where id = 'OKVsxSFS8SVbj9cyGnGdW';
update content_bodies set title = 'Tuna Cutting Show at Fisherman''s Wharf Shirahama', description = 'The ''Winter Fish Festival: The Tuna'' was held at Fisherman''s Wharf Shirahama, a seafood market directly operated by fishermen in Nanki Shirahama. The tuna cutting show, viewed from a close distance, offers an impressive and powerful experience. Fisherman''s Wharf Shirahama hosts seasonal fish festivals throughout the year. For more information about the facility and upcoming events, please visit their website.' where id = 'l3d43-tEhVZrrWwX8xw0m';
update content_bodies set title = '円月島', description = '円月島は白浜のシンボルとして親しまれており、正式には「高嶋」と呼ばれています。この小島は臨海浦の南海上に浮かび、南北130m、東西35m、高さ25mの大きさを持っています。島の中央には円月形の海蝕洞があり、その形状から「円月島」と名付けられました。円月島から見る夕陽は「日本の夕陽100選」に選ばれており、特に美しい夕景が楽しめます。夏は6時30分頃、冬は4時30分頃に日が沈みます。' where id = 'tHW6GunpEnt-1rFWfKpZU';
update content_bodies set title = 'Engetsu Island', description = 'Engetsu Island, officially known as Takashima, is a small island located off the coast of Shirahama, measuring 130 meters north-south and 35 meters east-west, with a height of 25 meters. It is affectionately called ''Engetsu Island'' due to the circular sea cave at its center. The sunsets viewed from Engetsu Island are recognized as one of the ''100 Best Sunsets in Japan,'' offering a particularly beautiful evening scene. In summer, the sun sets around 6:30 PM, while in winter, it sets around 4:30 PM.' where id = '4WJ42-P24y6W0w-9VlVAf';
update content_bodies set title = '白良浜', description = '白良浜は、延長620mの遠浅の浜で、90％の珪酸を含む真っ白でサラサラの砂が特徴です。この砂は非常に柔らかく、絵のような景観を作り出しています。夏になると、カラフルなパラソルが浜辺に点在し、弧を描く浜辺には椰子の葉パラソルが並び、トロピカルな雰囲気を一層引き立てます。' where id = 'TMoh9vFDyqu81kVToKjAq';
update content_bodies set title = 'Shirahama Beach', description = 'Shirahama Beach is a 620-meter long, shallow beach known for its fine, white sand that contains 90% silica. The sand is soft and powdery, creating a picturesque setting. During the summer, colorful umbrellas dot the beach, and palm leaf umbrellas line the curved shoreline, enhancing the tropical atmosphere.' where id = 'O4DbTRUGpmwmduRP3rODt';
update content_bodies set title = '千畳敷', description = '千畳敷は、その名のとおり広い岩畳を思わせる大岩盤です。瀬戸崎の先端から太平洋に向けて突き出したスロープ状の白く柔らかい岩は、第3紀層の砂岩から成り立っています。打ち寄せる荒波に浸食され、壮大な景観を創り出しています。' where id = '3rTFZIjiXp0q4Cd9yDmpZ';
update content_bodies set title = 'Chinjo-jiki', description = 'Chinjo-jiki, as its name suggests, is a vast rock platform resembling a wide rock pavement. This large rock formation, made of Tertiary sandstone, extends from the tip of Setozaki into the Pacific Ocean, featuring a sloped, soft white rock. The magnificent landscape is shaped by the relentless waves that erode the rock, creating a stunning natural scenery.' where id = '3zddDgfogffcuZCpMMCHI';
update content_bodies set title = '三段壁', description = '三段壁は千畳敷の南海岸に位置する高さ50m～60mの断崖です。「見壇」と呼ばれる漁師たちが船や魚を見張った場所に由来すると言われています。この大岩壁は南北に2kmにわたって広がり、黒潮が岩肌に激しく打ち寄せる様子は、自然の迫力を感じさせます。2016年4月には「南紀白浜/三段壁」として恋人の聖地に選定されました。' where id = '1tAmnBa9_EdNrKNxI409K';
update content_bodies set title = 'Sandanbeki', description = 'Sandanbeki is a towering cliff located on the southern coast of Chijō Beach, standing at a height of 50 to 60 meters. It is said to derive its name from a lookout point where fishermen once observed passing ships and schools of fish. This massive rock face stretches over 2 kilometers from north to south, showcasing a dynamic scene where the Kuroshio current violently crashes against the rocky surface, evoking a sense of nature''s power. In April 2016, it was designated as a ''Sacred Place for Lovers'' in Nanki Shirahama/Sandanbeki.' where id = 'AuICUON3dRaIWnuPoD_a0';
update content_bodies set title = '本州で一番早い海水浴場開き 南紀白浜『白良浜』', description = '南紀白浜の『白良浜』では、2024年度の海水浴場開きを5月3日に行います。本州で最も早い海水浴場開きで、早くて長い夏を楽しむことができます。白良浜で素晴らしい夏をお過ごしください！' where id = 'NJ8ZBgPE7BVygmjcBFAXA';
update content_bodies set title = 'The Earliest Beach Opening in Honshu: Shirarahama', description = 'The beach at Shirarahama in Nanki will open for the 2024 season on May 3rd, making it the earliest beach opening in Honshu. Enjoy a long and early summer at Shirarahama!' where id = '2_jTQWVJxeKEH26jgrVKD';
update content_bodies set title = '千畳敷｜シネマティック', description = '千畳敷は、その名の通り広い岩畳を思わせる大岩盤です。瀬戸崎の先端から太平洋に向けて突き出したスロープ状の白く柔らかい岩は、第3紀層の砂岩から成り立っています。打ち寄せる荒波によって浸食され、壮大な景観が生まれています。' where id = '7qI2XqR04jTKksdciHGLJ';
update content_bodies set title = 'Chinjo-jiki | Cinematic', description = 'Chinjo-jiki, as its name suggests, resembles a vast rock pavement. This large rock formation, made of Tertiary sandstone, extends from the tip of Setozaki into the Pacific Ocean, featuring a sloped, soft white rock. The relentless waves crashing against it have eroded the rock, creating a magnificent landscape.' where id = 'Fy9f3pvtWo_45K2bIWztn';
