update content_bodies set title = 'ダクトレールについている照明器具の外し方', description = 'この動画では、ダクトレールに取り付けられた照明器具の外し方を紹介しています。ダクトプラグは通常ロックがかかっており、ストッパーを下げることでロックを解除することができます。' where id = 'w_zmZCekiICJZpkiROVxC';
update content_bodies set title = 'How to Remove Lighting Fixtures from a Duct Rail', description = 'This video introduces how to remove lighting fixtures attached to a duct rail. The duct plug is usually locked, but it can be unlocked by lowering the stopper.' where id = 'qSruQxx9TOPemB157G-I_';
update content_bodies set title = '照明器具の外し方', description = 'この動画では、照明器具の外し方について紹介しています。引掛シーリングのロックに気づかずに強引に外そうとすると、壊れてしまう問題が多いことを指摘しています。ちょっとしたコツを使うことで、簡単に照明器具を取り外すことができる方法を説明しています。' where id = 'CzXtDt3mOV8IMzfLQZaQ7';
update content_bodies set title = 'How to Remove Lighting Fixtures', description = 'This video introduces how to remove lighting fixtures. It highlights a common issue where people attempt to forcefully remove fixtures without noticing the locking mechanism of the hook ceiling, which can lead to damage. The video provides simple tips to easily detach the fixtures without causing any harm.' where id = '65F4myK6KeVwSH-99FONi';
update content_bodies set title = '南紀白浜景勝地【円月島の夕陽】が真ん中に沈むまで', description = '南紀白浜の景勝地である円月島の夕陽が真ん中に沈む様子を描写しています。美しい夕焼けの瞬間を楽しむことができるスポットです。' where id = '5HLXOuIJVbWjsCNRK2-4d';
