update content_bodies set title = 'スマホで日常も旅も映画のように滑らかにDJIから新しく発売された「osmo mobile 8」', description = 'この動画では、DJIから新しく発売された「osmo mobile 8」について紹介しています。このデバイスは、スマートフォンを使って日常や旅行の体験を映画のように滑らかにすることを目的としています。高品質な映像を簡単に撮影できることが特徴です。' where id = 'd78_ySypqbwKNN50bOiFY';
update content_bodies set title = 'DJI''s New Osmo Mobile 8: Smooth Everyday and Travel Experiences', description = 'This video introduces the newly released ''Osmo Mobile 8'' from DJI, designed to make everyday life and travel experiences as smooth as a movie. The device promises to enhance smartphone videography, allowing users to capture high-quality footage effortlessly.' where id = 'wTPsfzf6E7onXdD2E92i5';
