update content_bodies set title = 'October 20, 2025', description = 'This video introduces October 20, 2025.' where id = 'hIgY4j1xVFI5h0dV_YzHX';
update content_bodies set title = 'MOARE｜木製照明のモアレ - 自然と調和した照明', description = '木製照明のモアレは、木のぬくもりと優しいあかりの融合から生まれる心地よさを大切にした日本のブランドです。岐阜県高山市の匠の技術を背景に、自然の本質に共鳴する製品を創造することを目指しています。木は私たちの心を和ませる効果があり、その感覚は私たちのDNAに根付いています。暗闇の中で小さな光が希望と安全をもたらすことを信じています。飛騨地域の伝統的な技術が、光と温もりのシナジーを高め、繊細な照明を通じてユニークな体験を提供します。モアレの使命は、世代を超えて大切にされる製品を生み出すことです。' where id = '1L8y68RHonA3w8UOKQcCI';
update content_bodies set title = 'MOARE｜Wooden Lighting in Harmony with Nature', description = 'MOARE is a Japanese brand of wooden lighting that emphasizes the comfort derived from the fusion of the warmth of wood and gentle illumination. Originating from Takayama in Gifu Prefecture, known for its craftsmanship, MOARE aims to create products that resonate with the essence of nature. The brand believes that wood has a calming effect on our minds, rooted in our DNA, and that even a small light can provide hope and safety in darkness. The traditional techniques of the Hida region enhance the synergy between light and warmth, offering a unique experience through delicate illumination. MOARE''s mission is to produce highly valued products that will be cherished for generations to come.' where id = 'miw88mJzBx9f51JwNNgG5';
update content_bodies set title = '壺阪寺-sakura-', description = '壺阪山 南法華寺（壺阪寺）は奈良県高市郡高取町に位置しています。住所は奈良県高市郡高取町壷阪3、郵便番号は635-0102です。この情報は2020年4月に制作されました。' where id = 'xFMVdBlHMX_OSHVhatMFm';
update content_bodies set title = 'Tsubosaka-dera - Sakura -', description = 'Tsubosaka-dera, also known as Nanpou Hōkaji, is located in Takaichi-gun, Takatori Town, Nara Prefecture, Japan. The address is 3 Tsubosaka, Takatori Town, Takaichi-gun, Nara 635-0102. This entry was created in April 2020.' where id = 'GMZtuY92M69Udw0_xB_gT';
update content_bodies set title = 'ANNA × creation(chase me)PV', description = '「chase me」のミュージックビデオにはダンサーの増田アンナが出演しています。彼女のInstagramはmoyashanna0603で確認できます。映像は若井渚が監督・編集を担当し、撮影は広瀬達司、ドローン撮影は高橋勉が行っています。音楽はJ.Crumによるものです。詳細はmvk.jp/creationで確認できます。' where id = 'GopOQCXTizHBLq3m0-KI6';
update content_bodies set title = 'ANNA × creation(chase me)PV', description = 'The music video for ''chase me'' features dancer Anna Masuda, whose Instagram can be found at moyashanna0603. The film is directed and edited by Nagisa Wakai, with cinematography by Tatsuji Hirose and drone work by Tsutomu Takahashi. The music for the video is provided by J.Crum. More information can be found at mvk.jp/creation.' where id = '3Asut2HKxn-Ft-TQ5E9uA';
