update content_bodies set title = '青い米って美味いの？さすがに日本では食べれないでしょ', description = 'この動画では、青い米について紹介しています。青い米は、特にマレーシアで見られるユニークな食材であり、その色合いが視覚的に魅力的です。日本では一般的に見かけないため、視聴者はその味や食文化について興味を持つことでしょう。動画を通じて、青い米の特徴や食べ方についての情報が提供され、海外旅行や異文化体験に興味がある人々にとって新たな発見となる内容です。' where id = 'UHv07JLkkjxsKF9dpmTlJ';
