update content_bodies set title = 'カンボジアは2種類の通貨が使える？', description = 'この動画では、カンボジアで使用されている2種類の通貨について紹介しています。カンボジアでは、現地通貨のリエルとアメリカドルが流通しており、観光客や地元の人々が日常的に利用しています。リエルは主に小額の取引に使われる一方、ドルは大きな取引や観光地での支払いに広く使われています。このように、カンボジアでは2つの通貨が共存しており、旅行者にとっても便利な環境が整っています。' where id = 'FzEt-9q66SG1G3dyK4DIy';
