update content_bodies set title = 'ビジネスクラスってこんな感じなの？', description = 'この動画では、ビジネスクラスについて紹介しています。ビジネスクラスの特徴やサービス内容、快適さなどが取り上げられており、海外旅行を楽しむ人々にとっての魅力が伝わります。特に、飛行機での移動を快適に過ごすための情報が得られる内容となっています。' where id = 'hFpi0Q3hiqc7NYPUL4F-e';
