update content_bodies set title = 'Kanmon Area (Shimonoseki and Mojiko Retro) Drone Footage (3-Minute Version)', description = 'This 3-minute video showcases the tourist attractions of the Kanmon area, connecting Shimonoseki and Mojiko through the Kanmon Strait. Although the two cities are only a 5-minute ferry ride apart, their atmospheres are similar yet distinct. The footage captures the history of each city, inviting viewers to compare and enjoy the differences.' where id = 'ENKV6d3DJjnCJECHgWyG_';
