update content_bodies set title = 'Kokura Castle Area', description = 'The central area of Kokura in Kitakyushu includes Kokura Castle, the Kitakyushu City Hall, and Katsuyama Park. The ''Murasaki River'' flows through the city center and features ten bridges designed with a nature theme, symbolizing the natural restoration of the river, seamlessly blending into the urban landscape.' where id = 'kCxjLFzwmu8PJiX2MIZAJ';
