update content_bodies set title = '海外に来て思った日本の良いところ3選', description = 'この動画では、海外に来て感じた日本の良いところを3つ紹介しています。日本の文化や習慣、生活の質など、驚くべき点がたくさんありました。特に、他国と比較して際立つ日本の特徴や、日常生活の中での便利さ、そして人々の親切さについて触れています。これらの要素が、日本を特別な場所にしていることを実感しました。' where id = 'CS2axsa64iNQiPRN6HViY';
