update content_bodies set title = '海外に来て驚いたこと3選', description = 'この動画では、海外に来て驚いたことを3つ紹介しています。海外生活を始めた人々が直面する意外な体験や文化の違いについての感想が語られています。視聴者は、他の人々がどのようなことに驚いたのかを知ることができ、海外生活のリアルな一面を垣間見ることができます。' where id = 'rjRRFhA1e9zW0UouGyzc9';
update content_bodies set title = 'Three Surprising Things About Living Abroad', description = 'This video introduces three surprising things that people experience when they come to live abroad.' where id = 'WVqoO1E3jPvbuEIzA3D5L';
update content_bodies set title = '海外の田舎に留学は最高に楽しい！英語も覚えられる！', description = 'この動画では、海外の田舎での留学体験について紹介しています。田舎の環境での学びは、英語を学ぶだけでなく、異文化体験や自然とのふれあいを通じて、学生にとって非常に楽しいものとなります。田舎ならではの生活や人々との交流が、留学をより豊かなものにするでしょう。' where id = 'It6HZIPMkPyHjHd-ldRqT';
