update content_bodies set title = '留学に持って行ったほうがいいものって何！？みんなのおすすめ教えて！', description = 'この動画では、留学に持って行くべきアイテムについてのおすすめを紹介しています。留学を考えている方にとって、必要なものや便利なアイテムを知ることは非常に重要です。視聴者は、実際に留学を経験した人々の意見やアドバイスを参考にすることができ、準備を整える手助けとなるでしょう。' where id = '_dc1vx46ZIAM51R3ThTqf';
